/* CHI participant menu — content.
   Stages, the tiles, the icon set, placement names, CHI contacts, route wording.
   This is the file a coordinator edits. No logic, no secrets. */

const STAGES = [
  {n:1, key:'home', t:'I am still in my country', z:'My country',   d:'I have not flown to the United States yet.', c:'Visa, flights, dates, housing, my documents'},
  {n:2, key:'arr',  t:'I just arrived',            z:'Just arrived', d:'I landed in the last two weeks.',            c:'First day, SEVIS, Social Security, housing'},
  {n:3, key:'work', t:'I am working',              z:'Working',      d:'Questions about my job, my hours and my pay.', c:'Hours, pay, my manager, changing jobs'},
  {n:4, key:'life', t:'Living in the USA',         z:'Living here',  d:'Everything that is not about my job.',        c:'Health, safety, documents, travel, housing'},
  {n:5, key:'end',  t:'My program is ending',      z:'Ending',       d:'I am close to my end date or already home.', c:'Going home, final pay, taxes, next year'}
];

const T = [
{s:'home', q:'When is the next online orientation', sub:'Sessions, attendance, the certificate', g:'Before you book anything', ic:'webinar', r:'Answer', k:'orientation session webinar zoom next when schedule missed attendance certificate mandatory link slides recording gba absent marked student training register',
 you:"You start <b>{dsStartF}</b>.[[ Orientation attended: <b>{orientationAttended}</b>.]]",
 lead:"Join a session before your start. Cannot join? Tell your CHI team before the session, not after.",
 body:["The dates come by email and by WhatsApp.","Your Zoom name is your full name and your Student ID <b>{sid}</b>.","Fill in the attendance form during the session.","Marked absent, but you were there? Message my CHI team with the date and the Zoom name you used."],
 need:['The date of the session','The name you used in Zoom','Your Student ID'],
 act:{label:'I was marked absent but I was there', kind:'team'},
 w:{trigger:'Tile opened, or the action tapped', fires:'Nothing automatic', captures:'Session date, Zoom display name used, SID', notify:'Coordinator, batched not immediate', log:'Orientation Log corrected against the SID', status:'build', note:'This is the biggest single thing in the orientation data and it is not a programme question at all. 134 of 771 questions asked in the sessions, 17 percent, are about the attendance link failing, being marked absent after attending, or whether there is another session. Two of those three are a form problem rather than a participant problem: the Tally window closes at the end of the session and the Zoom display name has to carry the SID for matching to work. Fixing the form removes most of this tile. Until then the tile at least stops the question arriving as a WhatsApp message during the session itself.'}},
{s:'home', q:'My visa appointment', sub:'Visa, embassy, DS-160', r:'Answer', mo:['embassy_status','Embassy Status Update Request, or Embassy Denial if the visa is refused. Greeting resolves to the agency POC from the lookup table.'], g:'Before you book anything', ic:'passport', k:'visa embassy consulate ds160 interview appointment ds-160 sevis fee emergency appointment expedite proof of program sevis 901 pink slip issued approved status',
 you:'[[You are in <b>{country}</b>.]] Message my CHI team about your visa. That opens an email to your coordinator.',
 lead:'CHI does not book the embassy appointment. Message my CHI team. That opens an email to your coordinator.',
 body:['CHI gives you your DS-2019. CHI pays your SEVIS fee.','For the DS-160, the appointment date, and the interview, Message my CHI team.','Is your appointment after your start date? CHI can write a letter to move your dates.','For an expedited appointment, your proof of program is your DS-2019 from the portal.','Your SEVIS fee receipt is the payment receipt. CHI cannot reissue it.','Issued online usually means your passport is on its way.'],
 need:['Your DS-2019, the paper one','Your SEVIS fee receipt','Your job offer'],
 act:{label:'Message my CHI team', kind:'chi'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'Highest volume question in the whole inbox at 622 replies. Pure answer, no CHI action, no form. Build this one first.'}},
{s:'home', q:'Where is my DS-2019', sub:'Waiting for my DS form', g:'Before you book anything', ic:'docn', r:'Team', k:'ds2019 ds-2019 ds form coming waiting arrive sent tracking not received where is my form document sponsor letter sponser job offer difference certificate eligibility replacement reprint number',
 you:"[[You are in <b>{country}</b>.]] CHI issues your DS-2019. When it arrives, the dates should read <b>{dsStartF|the dates on the form}</b> to <b>{dsEndF|the dates on the form}</b>. Message my CHI team if it has not come. That opens an email to your coordinator.",
 lead:"CHI issues your DS-2019. If you do not have it, Message my CHI team. That opens an email to your coordinator.",
 body:["Is your interview close and the form has not arrived? Message my CHI team today.","The day it arrives, check your name as it is in your passport, your date of birth, and the start and end dates.","Is something wrong? Say so before the embassy. Photograph the form. A replacement costs 75 dollars.","Bring the paper form. A photo on your phone is not accepted.","It is not the same as your job offer or your sponsor letter. You need all three.","DS Number on file: <b>{dsNumber|omit}</b>."],
 need:["Your embassy appointment date, if you have one"],
 act:{label:'Message my CHI team', kind:'chi'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'Routes to the agency named from Agency Office Code, which is why the tile can say who to chase instead of saying your agency. The three checks matter more than the chasing: a name or date error caught before the embassy appointment costs nothing, and the same error caught after the visa is issued becomes a correction letter and a delayed arrival.'}},
{s:'home', q:'I need to change my start date', sub:'Delays, exams, moving my dates', g:'Before you book anything', ic:'calswap', r:'Team', k:'dates change start date end date university exams classes term semester study go home early late master degree graduation school starts delay delayed late visa embassy correction letter push back postpone',
 you:'Your programme runs <b>{dsStartF}</b> to <b>{dsEndF}</b>, and <b>{employer}</b> built their season around the first of those.',
 lead:'Your employer has to agree before any date moves, and they need warning. Use Message my CHI team at the bottom of the page as soon as you know.',
 body:['The two reasons dates move are a delay and your university. A delay is your embassy appointment, your visa or your DS-2019 arriving late. Your university is exams finishing after your start date, or term beginning before your end date.','If your exams end after your start date, use Message my CHI team now, not in May. A few days late can sometimes be arranged with the employer. A few weeks cannot.','If your classes start before your end date, say so now. It is much easier to shorten a programme before it is issued than after you have arrived.','If you are a postgraduate with no fixed autumn classes, or it is your final year, you still need proof you are enrolled. Bring it.','If something is delaying you, your embassy appointment, your visa, your DS-2019 or an exam that moved, use Message my CHI team the moment you know. Do not wait to see whether it resolves itself.','A few days late can usually be arranged with the employer. A few weeks often cannot, and the placement can go to somebody else.','CHI can issue a correction letter to move your dates, but only after your employer agrees, and it is far simpler before your DS-2019 has been used at the embassy.','If your dates changed after your visa was issued, your DS-2019 and your correction letter will not match. That is normal. Carry both, and never travel with only one of them.','CHI does not have your academic calendar. Message my CHI team and tell them the dates you know. That opens an email to your coordinator.'],
 need:['Your term start date','Your exam dates','Written proof you are still enrolled'],
 act:{label:'Message my CHI team', kind:'chi'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'Merged from two tiles because the orientation questions show it is one problem. Across 899 orientation questions, university term dates come up repeatedly and always as a dates question: exams after the start date, classes before the end date, no autumn classes for postgraduates. Routes to the agency named from Agency Office Code. CHI has been asked to confirm return dates it cannot know, which is why this tile never offers an answer.'}},
{s:'home', q:'Can CHI check my housing is not a scam', sub:'Before I pay anyone anything', g:'Before you book anything', ic:'shieldalert', r:'Team', hz:1, k:'scam fraud fake housing check verify landlord deposit facebook money transfer before i pay lease listing safe legit crypto is this legit is this email real spam call telegram someone asking for money fake job',
 you:'You are placed with <b>{employer}</b> in <b>{location}</b>. If housing is not provided there, send CHI anything you find before you pay a cent.',
 lead:'Yes, and send it before you pay anything. After the money is gone CHI cannot get it back.',
 body:['Send your CHI team the listing, the address, the landlord full name and their phone number. That takes a day to check and it is free.','These are the signs. They want the whole deposit by bank transfer, gift card or crypto before you have seen anything. The price is far below everything else in the same town. They will not do a video call. They say they are abroad and cannot show you the place. They push you to decide today.','Never send money to someone you have only met in a Facebook group or a WhatsApp chat without CHI looking at it first. That is where almost all of these start.','Ask for the lease in writing before you pay. A real landlord will give you an address, a full name, a phone number and a lease. If you cannot get all four, you have your answer.','If you have already sent money and it has gone wrong, tell your CHI team anyway. It may be too late for the money, but not for your housing.','Unsure whether a message, a job offer, or a caller is real? Forward it to your coordinator before you answer. CHI cannot get a deposit back for you.'],
 need:['The listing or the advert','The address','The landlord full name and phone number','What they are asking you to pay, and how'],
 act:{label:'Ask CHI to check this housing', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'Listing, address, landlord name and number, amount and payment method requested', notify:'Coordinator, marked time sensitive because money is usually about to move', log:'Case row, category Housing. Address flagged if it matches an earlier report', status:'build', note:'Only bites for participants whose employer does not provide housing, which is a minority but the one with real money at risk. Worth logging the addresses: a scam listing gets sent to a whole cohort, so the second report at the same address should be instant rather than another day of checking.'}},
{s:'home', q:'How early can I arrive', sub:'Arriving before my start date', g:'Before you book anything', ic:'shieldplane', r:'Answer', k:'early arrive how many days before start date insurance uninsured supplement land arrive early extra cover arrival seven early-arrival ideally 3 to 5 days ds-2019',
 you:"Hi <b>{firstName|there}</b>. Your programme starts <b>{dsStartF}</b>. Insurance covers you from <b>{insStartF}</b> to <b>{dsEndF}</b>. You can land from <b>{insStartF}</b> without buying extra cover.",
 lead:"Land from 7 days before your start date and you are covered. Earlier than that, tell your CHI team before you buy the ticket.",
 body:["Arrive before your DS-2019 start date, never after it. Ideally, arrive 3 to 5 days before it.[[ Your start date is <b>{dsStartF}</b>.]] Do not start work before <b>{dsStartF|your start date}</b>.","Will you land before <b>{insStartF}</b>? Message my CHI team the exact date first, so early cover can be set up.","Housing often opens only a few days before your start. Do not arrive on a weekend or a holiday unless <b>{employer|your employer}</b> agrees."],
 clock:{l:'Before you book', t:'Tell your CHI team your landing date before you buy the ticket, not after.'},
 need:["The day you plan to land","The start date on your DS-2019"],
 act:{label:'Tell my CHI team my landing date', kind:'form'},
 w:{trigger:'Arrival Date minus DS Start is 8 days or more', fires:'Early arrival insurance notice with the cost, to the participant and their agency', captures:'Landing date, uninsured days, supplement owed', notify:'Coordinator', log:'Msg_Early_Arrival_Insurance stamped on the roster row', status:'build', note:'The seven day line is the whole answer and the tile now says it as a date rather than a rule, so nobody has to count. 14 participants landed 8 to 21 days early this season, roughly 1450 dollars of exposure, and the roster column for this trigger already exists while the trigger itself does not.'}},
{s:'home', q:'Where do I enter my visa results', sub:'After the embassy, approved or refused', g:'Before you fly', ic:'visastamp', r:'File', k:'visa result approved refused denied embassy interview enter report portal administrative processing passport back stamp 221g slip color try again',
 you:"Your programme starts <b>{dsStartF|your start date}</b>.[[ Interview on file: <b>{embassyInterview}</b>.]]",
 lead:"As soon as the embassy gives you a date, enter it at wt.chinet.org on the Visa page. Enter the result the day you leave the embassy.",
 body:["Path: My Profile, then Visa, then the embassy interview date. Still blank close to <b>{dsStartF|your start date}</b>? Message my CHI team.","Approved: enter the date you received the visa, and add a photo of the visa page. Check your name, your date of birth, and whether Entries says M or S.","Denied: enter the denied date. Want to try again this season? Write Try again in the comments so CHI can hold the job. No comment, and CHI may release it.","Administrative processing, also called 221(g): check the embassy case-status site. It often updates first. In the comments, write the slip color: Pink, Blue, Yellow, or White.","Do not book a flight until the visa is in your passport.","Visa received on file: <b>{dateVisaReceived|omit}</b>.","Visa approved on file: <b>{visaApproved|omit}</b>."],
 need:["Your interview date","The result","A photo of the visa page, once you have it"],
 act:{label:'Enter my visa result', kind:'form'},
 w:{trigger:'Form submitted. Chased at DS Start minus 30 if still blank', fires:'Approved: arrival information unlocked. Refused: Embassy Denial to the agency contact. Administrative processing: Embassy Status Update', captures:'Interview date, result, visa page image, Entries M or S', notify:'Coordinator. Agency contact on a refusal', log:'Date Visa Received, Date Visa Denied and Visa Approved written to the roster', status:'build', note:'The roster already has all three columns and nothing feeds them. CHI Advisor already has Embassy Denial and Embassy Status Update written, so the sends exist and only the capture is missing. Catching Entries S here rather than in July is the other reason for the tile: a single entry visa changes every travel answer for the whole programme.'}},
{s:'home', q:'Where do I enter my flight details', sub:'Flights, airport, landing date', r:'File', g:'Before you fly', ic:'plane', k:'flight ticket airport arrival landing itinerary plane airline layover save flights uber lyft taxi immigration return ticket arrangements flight time resets no flight yet departure flight return flight',
 you:"[[We have you landing on <b>{arrivalF}</b>]][[ into <b>{arrivalAirport}</b>]][[ on <b>{arrivalAirline}</b> <b>{arrivalFlight}</b>]]. Your programme starts <b>{dsStartF}</b>. If a detail is missing, enter it.",
 lead:"Enter the airline, the flight number, and the arrival at wt.chinet.org as soon as you book. Use the final U.S. airport, not a layover.",
 body:["Enter each flight, then click Save Flights before you add the next one.","Put the arrival date and time in the arrival section only. Never put them in the departure section.","CHI uses this to check your insurance and the address in SEVIS. Also send the details to <b>{employer|your employer}</b>.","Nobody picks you up. Plan your own ride to <b>{location|your town}</b>. Landing late? Stay at a hotel first and travel in daylight.","Staying somewhere else first? Write that plan in Additional Arrangements.","Immigration can take an hour or more. Use a licensed taxi, Uber, Lyft, or an airport shuttle.","Unsure about a return ticket? Message my CHI team.","No flight booked yet? Enter your best estimate, then update it as soon as you book. You can add the flight home later.","Did your plans change? Update the portal."],
 need:["Airline and flight number","Landing airport and landing date","Your first US address if you already have it"],
 sample:{title:'Email you can send your employer', lines:[
   'Subject: My arrival details, {name}',
   '',
   'Dear [manager name],',
   '',
   'My name is {name} and I am joining you at {employer} in {location} as a {job}.',
   '',
   'My programme starts on {dsStartF}. Here are my arrival details:',
   '',
   'Landing airport: [airport]',
   'Landing date: [date]',
   'Landing time: [time]',
   'Airline and flight number: [flight]',
   '',
   'Please can you confirm where I should go on my first day, what time to be there, and who to ask for.',
   '',
   'Thank you, and I am looking forward to the season.',
   '',
   '{name}',
   'CHI Student ID: {sid}']},
 act:{label:'Send my flight details', kind:'form'},
 w:{trigger:'Form submitted', fires:'Flight Information template to the participant', captures:'Flight number, landing date, arrival airport, first address', notify:'Log row only', log:'Arrival Date, Arrival Airport, Arrival Airline and Arrival Flight Number written to Staging Participants', status:'build', note:'No flight form exists yet. Roster already has Arrival Date, Arrival Airport, Arrival Airline and Arrival Flight Number columns waiting to be fed.'}},
{s:'home', q:'Where do I verify my housing', sub:'Where I will live, and getting it verified', hz:1, g:'Before you fly', ic:'housekey', r:'File', k:'housing house live where stay accommodation room apartment before arrive rent cost landlord verify verified address sevis link form verification four weeks liability release housing form housing verification verify my stay student id on the form which id zip code housing reminder email I already did it staying with family hotel housing employer housing contract lease',
 you:"You are placed with <b>{employer|your employer}</b> in <b>{location|your town}</b>. You start <b>{dsStartF}</b>.[[ Housing status: <b>{housingStatus}</b>.]][[ Approved address: <b>{housingAddress}</b>.]]",
 lead:"Housing must be verified at wt.chinet.org at least 4 weeks before you arrive. Without that verification, CHI cannot activate SEVIS.",
 body:["Include the apartment or room number. Will you live with family? They must sign a Liability Release. Email your coordinator for it.","It is required even when your employer gives you housing. It is a government rule.","Student ID on the form means your CHI Student Program ID, on your portal home page. It is not your university ID or your SEVIS number.","The address must be the one you will use for SEVIS, including the room or unit number.","Got a reminder after you submitted? If your status shows verified, you can ignore it.","CHI must enter your U.S. address in SEVIS before you land. Without it you can be turned away at the border.","Did the address change? Send the new one."],
 need:["The full address and unit","The landlord name and phone","The weekly cost","The move-in date"],
 act:{label:'Get my housing verified', kind:'form'},
 w:{trigger:'Form submitted. Chased at DS Start minus 21 and minus 10 if nothing has been received', fires:'Verification confirmation to the participant once the address passes', captures:'Full address with unit number, provider name and phone, weekly cost, move in date', notify:'Coordinator if it arrives under 10 days before landing, or not at all', log:'Housing Approved Address and Housing Status written to the roster', status:'build', note:'No form exists for this yet and it is the one pre-arrival tile with a hard consequence: no address in SEVIS means a participant can be turned away at the border. The required wording is Jenn own and must go out unchanged. The chase matters more than the form: the failure mode is not a wrong address, it is no address at all, and nothing currently watches for silence.'}},
{s:'home', q:'What airport should I fly into', sub:'Choosing the airport and getting out of it', g:'Before you fly', ic:'depart', r:'Answer', k:'airport fly into best nearest which airport transport shuttle pickup taxi bus train from the airport late night transfer connection two flights uber',
 you:'You are going to <b>{location}</b>. Before you book, ask your CHI team which airport other people at <b>{employer}</b> use.',
 lead:'Fly to the airport named on your job offer. Is no airport named? Ask before you book.',
 body:['The closest airport is not always the right one. And the cheapest flight is often not the cheapest trip.','A cheap flight to a big airport four hours away costs more, once you pay to get from there to your housing.','Before you book, work out how you will get from the airport to your housing. Most employers do not pick you up. Your job offer says so if yours does.','Are you landing in the evening? Check the last bus or train first. In small towns there is often nothing at night. A taxi can cost more than your flight did.','Keep money for this trip. It can be a hundred dollars or more. That money comes out of what you brought for your first two weeks.','Do you have two flights? Only put the flight that lands in the USA into your portal.','Landing late at night with no way to get there? Tell your CHI team before you book. Not after.'],
 need:['Your job offer','The address of your housing','Your airport and your landing time'],
 act:{label:'Ask my CHI team about my area', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Asked in the orientations about Fairbanks, Estes Park and other remote placements, where the honest answer is that there may be no transport after the evening at all. The right airport per host area is a short list CHI could write once and reuse every season, shown from Location Name.'}},
{s:'home', q:'When should I contact my employer', sub:'Reaching them before I fly', g:'Before you fly', ic:'envelope', r:'Team', k:'contact employer reach out email phone number job description no response reply before arrival week before manager',
 you:"Your employer is <b>{employer|your employer}</b>[[ (<b>{employerDba}</b>)]] in <b>{location|your town}</b>[[ / <b>{employerCity}</b>]]. Your job is <b>{job|your job}</b>. You start <b>{dsStartF}</b>.[[ Manager on file: <b>{managerName}</b>.]]",
 lead:"Make sure they have your arrival date before you fly. After you land, if your first day is not confirmed, call or text during business hours.",
 body:["Use the contact on your job offer.[[ Phone on file: <b>{employerPhone}</b>.]]","Send your name, your Student ID <b>{sid}</b>, your job, and your landing date. Ask where to go, what time, and who to ask for.","One quiet week before the season is normal. Two quiet weeks? Message my CHI team."],
 need:["Your job offer","The date you wrote to them","Any reply you got"],
 act:{label:'Nobody has replied, tell my CHI team', kind:'team'},
 w:{trigger:'Form submitted, only when they escalate', fires:'Nothing automatic', captures:'Date emailed, contact used, whether any reply came', notify:'Coordinator', log:'Case row, category Communication, only if escalated', status:'build', note:'Straight from the orientation questions: no phone number on the job description, no reply after nine days, and job offers that say contact your employer a week before arrival while giving a contact that does not answer. The tile mostly exists to set the expectation that slow is normal, which stops the message arriving at CHI on day three.'}},
{s:'home', q:'WhatsApp groups for my employer', sub:'The group for my employer', g:'Before you fly', ic:'chatgroup', r:'File', k:'whatsapp group add me chat added join not in the group number sim employer group left group removed link city cluster eastern',
 you:"You are placed with <b>{employer|your employer}</b> in <b>{location|your town}</b>. Your coordinator is <b>{coordinator|Jenn}</b>.[[ Your group: <b>{waGroupName}</b>.]]",
 lead:"CHI adds you to your city or employer WhatsApp group closer to your start. You can message your coordinator Monday to Friday, 9am to 5pm Eastern.",
 body:["Join link, if it is ready: <b>{waGroupLink|omit}</b>.","No link yet? Message my CHI team and ask to be added.","We keep a WhatsApp number on file. Message my CHI team if you changed your SIM.","Pay, housing, and documents go to Message my CHI team, not the group."],
 need:["Your WhatsApp number, with the country code"],
 act:{label:'Add me to the group', kind:'form'},
 w:{trigger:'Form submitted', fires:'Confirmation once added', captures:'WhatsApp number with country code, employer', notify:'Coordinator, to add them', log:'WhatsApp column updated on the roster', status:'build', note:'Adding is manual, so the value here is the number, not the request. The roster WhatsApp column is what every group invite and every direct message runs off, and it goes stale the moment someone buys a US SIM. This tile and the US phone number tile in the arrival board write to the same column, which is deliberate: one before they fly, one after they land.'}},
{s:'home', q:'Where is my job description or offer', sub:'Job offer and job description', g:'Before you fly', ic:'formsign', r:'Answer', k:'job offer description contract where find portal download signed saved copy lost access pay rate housing hours position my id',
 you:"CHI has you as <b>{job|your job}</b> at <b>{employer|your employer}</b> in <b>{location|your town}</b>, starting <b>{dsStartF}</b>.[[ Position ID <b>{positionId}</b>.]]",
 lead:"Download it at wt.chinet.org, under My Job. It stays there after you sign.",
 body:["Check the employer, the town, the job, the pay, the hours, and the housing. Print two copies. One for the embassy. One for your first day.","Does the job differ from the paper? Message my CHI team. The paper is your proof."],
 need:["Your portal login"],
 act:{label:'Ask my CHI team for my job offer', kind:'team'},
 w:{trigger:'Tile opened, or the action tapped', fires:'Nothing automatic. A person sends it if the portal copy is missing', captures:'Nothing', notify:'Coordinator only when they ask for it', log:'Page view only', status:'live', note:'The most referenced document in the whole menu. Twelve other tiles tell a participant to check something against their job offer, so a tile that says where it is has more leverage than its own question volume suggests. The personal line is doing real work here: it prints the four fields from the roster and asks the participant to compare them with the paper, which is the cheapest possible check on a placement record being wrong.'}},
{s:'home', q:'What documents do I need', sub:'The six papers to carry', g:'Before you fly', ic:'docstack', r:'Answer', k:'documents papers passport ds2019 visa job offer sponsor letter enrolment student proof insurance card i94 carry hand luggage what do i need bring carry-on checklist emergency contacts envisage sid signature student id',
 you:"<b>{firstName|You}</b>, you fly to <b>{location|your placement}</b> and start <b>{dsStartF}</b>. Your Student ID is <b>{sid|on your portal}</b>. Keep the originals in your hand luggage only.",
 lead:"Carry and photograph your passport with the J-1 visa, your DS-2019, your job offer, your sponsor letter, proof you are a student, your insurance card, and your emergency contacts.",
 body:["The CHI emergency line is 1-800-432-4643, ext. 0. It is open 24/7. Also keep your employer and your family as contacts.","Put your Student ID in every message to CHI. A useful subject is Work and Travel, then <b>{sid|your Student ID}</b>, then <b>{firstName|your name}</b> <b>{last|}</b>, then the topic.","Print the Emergency Card from wt.chinet.org, write your Student ID on it, and keep it in your wallet. On your lock screen, put your Student ID and CHI 1-800-432-4643, ext. 0. That line is open 24/7.","Download your insurance card from the Envisage Student Zone before you fly. Keep a photo with your passport.","Use the exact name from your passport on every form.","At the border: passport and DS-2019. On day one: those, plus your printed I-94. Print the I-94 after you land.","Do not laminate the DS-2019. Do not fold it. Carry medicine, a charger, and these papers in your hand luggage."],
 need:["Passport and J-1 visa","DS-2019","Job offer","Sponsor letter","Proof you are a student","Insurance card"],
 act:{label:'Send me the document checklist', kind:'template'},
 w:{trigger:'Tile opened, and on a send at DS Start minus 14', fires:'Document checklist', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'build', note:'Split out from what should I bring because the two lists behave differently: forget a jumper and you buy one, forget the DS-2019 and you do not board. The sponsor letter is on here deliberately even though nothing at the airport asks for it, because it is the item people leave at home and then need at the Social Security office ten days later. No template written yet.'}},
{s:'home', q:'Where can I find my sponsor letter', sub:'The letter that says CHI sponsors you', g:'Before you fly', ic:'letter', r:'Answer', k:'sponsor letter sponser visa sponsor where find get portal social security office not the job offer difference',
 you:"It should show your name, your Student ID <b>{sid}</b>, and your dates <b>{dsStartF}</b> to <b>{dsEndF}</b>.",
 lead:"Download it from wt.chinet.org. Is it missing? Message my CHI team.",
 body:["It is not your job offer. It is not your DS-2019. The Social Security office, and some banks, ask for it by name. Print it before you fly."],
 need:["Your portal login"],
 act:{label:'Ask my CHI team for my sponsor letter', kind:'team'},
 w:{trigger:'Tile opened, or the action tapped', fires:'Nothing automatic. The letter is sent by a person if the portal copy is missing', captures:'Nothing', notify:'Coordinator only when they ask for it', log:'Send logged against SID', status:'build', note:'Asked five separate times in the orientation Q and A, always as some version of what is the sponsor letter and how is it different from the job offer. Two things to confirm before this goes live: whether the letter actually sits in the participant portal alongside the DS-2019 copy and the proof of address, and whether it can be generated on demand. If it is not in the portal, this becomes a File tile with a request form rather than an Answer tile.'}},
{s:'home', q:'What should I bring', sub:'Documents, clothes, money, medicine', g:'Before you fly', ic:'suitcase', r:'Answer', k:'bring pack packing documents clothes weather cold hot medicine prescription vaccine vaccination supplements food money cash phone unlock sim carry on suitcase 1500 paycheck frostbite winter layers marijuana cigarettes vapes alcohol 21 federal esim dentist teladoc 250',
 you:"You are going to <b>{location|your town}</b> for <b>{season|your season}</b>. You start <b>{dsStartF}</b>. Check the real temperatures there.",
 lead:"Bring at least 1,500 dollars you can use, because your first paycheck can take 2 to 3 weeks. About 500 dollars of that should be cash. Bring medicine in the original boxes, with the prescription. Bring an unlocked phone, a U.S. plug adapter, and shoes you can wear all day.",
 body:["Tell your bank you are traveling.","Your documents are on a separate tile.","Unlock the phone before you leave home. Add an eSIM if you want data on landing, and download offline maps.","Book a doctor and a dentist at home before you fly. Dental cleanings, fillings, glasses, and contacts are not covered.","CHI insurance is for a new illness or injury. You usually pay the first 250 dollars of each new problem.","See a doctor and a dentist before you fly. Bring a 3-month supply of medicine in your carry-on, with a translated prescription. Bring an extra pair of glasses. Routine dental care and vision care are not covered.","Install the Teladoc app before you fly. It works only in the United States, and only after your cover starts.","You must be 21 to buy cigarettes, vapes, or alcohol. Marijuana is illegal under federal law for J-1 participants, even where a state allows it.","{winterNote|omit}"],
 need:["1,500 dollars you can access","Medicine and the prescription","An unlocked phone","Work shoes"],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened, and on a send at DS Start minus 14', fires:'Nothing on view', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'This was a thin tile until the orientation questions were read. What they actually ask about is clothes for the weather where they are going, whether they can bring their own medicine, vaccines and supplements, and whether their phone will work. The climate line personalises off Location Name, which is the only part that varies. Worth firing as a send two weeks before departure rather than waiting to be asked.'}},
{s:'home', q:'Can I get a second job before I arrive', sub:'Arranging one from home', g:'The job and the money', ic:'twobags', r:'Answer', k:'second job before i arrive get find arrange mandatory need required extra work another job apply now form when from home wait',
 you:'Your main job is <b>{job}</b> at <b>{employer}</b>. That is the one your programme is built on.',
 lead:'No. You cannot set one up before you land. And you do not have to have one at all.',
 body:['Your first job comes first, always. A second job has to fit around that schedule.','Do not say yes to a second job before you land. You will not know your main hours until you start. And they change every week.','Do not fill in the second job form now. Fill it in when you have a real offer in front of you.','CHI must approve any second employer before your first shift there. Working somewhere CHI has not approved puts your visa at risk.','Most people who want a second job find one after a few weeks. By then they know their main hours and they know their area.','So the answer for now is: wait. There is nothing you need to do today.'],
 need:[],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Second job was 5 percent of all orientation questions, asked before arrival, and almost every one of them was is it mandatory, where do I find one, or should I fill the form now. All three have the same short answer, which is why this is an Answer tile here and a File tile in the working board.'}},
{s:'home', q:'Can I start my Social Security', sub:'Applying before I arrive', g:'The job and the money', ic:'card', r:'Answer', k:'social security ssn apply before arrive now online start application sponsor letter visa appointment book activation returnee control number seven business days ssa.gov plattsburgh',
 you:"Your programme starts <b>{dsStartF}</b>.[[ Has Social Security Card on file: <b>{hasSSN}</b>.]]",
 lead:"You can start the online Social Security application before you fly. Do not walk into the office until the visa activation email.",
 body:["Already have a number? It is good for life. Apply again only if the card is lost: https://www.ssa.gov/number-card/replace-card . First time: https://www.ssa.gov/number-card/request-number-first-time .","No U.S. address yet? You may temporarily use your employer address[[ <b>{employerAddress}</b>]][[, phone <b>{employerPhone}</b>]]. Change it to your housing address at the appointment.","Save the Online Control Number. It starts with the letter O. It is on the yellow screen that says the request is not complete. Screenshot it and email it to yourself. Give it to the officer. If the site errors from outside the United States, finish those steps after you land. Do not email CHI only about that error.","Book the earliest appointment on or after about 7 business days after you land, and only after the activation email. Do not attend before that email.","Office: <b>{ssaOfficeName|omit}</b>.","Office address: <b>{ssaOfficeAddress|omit}</b>.","Office phone: <b>{ssaOfficePhone|omit}</b>.","ZIP for booking: <b>{ssaZip|omit}</b>.","No office on file? Use ssa.gov/locator.","The site fails from home sometimes. Finish those steps after you land. You can work with the receipt before the card arrives.","Ask the card to be mailed to your housing, not to your employer.","{plattsburghNote|omit}","Is the sponsor letter missing? Message my CHI team."],
 need:["Your passport","Your DS-2019","Your sponsor letter"],
 act:{label:'Send me the Social Security steps', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'SSN next steps template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'fix', note:'Social Security was 8 percent of orientation questions and most of them were asked before arrival: can I apply now, can I apply without the visa, where is the sponsor letter. The answer is no and here is the order, which is cheap to give early and expensive to give late. Same template gap as the arrival tile: no SSN template has been written yet.'}},
{s:'arr', q:'Where do I go on my first day', sub:'First day, reporting, who to ask for', r:'Answer', mo:['intervention','Intervention Required, only when nobody at the employer is expecting them.'], ic:'doorin', k:'first day arrive report where go employer start manager check in nobody expecting phone punctual workplace culture daylight saving clock start date begin when can I arrive arrive early arrive late welcome center correction letter print the letter earlier date',
 you:'Go to <b>{employer}</b> in <b>{location}</b>. Your job title is <b>{job}</b>. The address and the manager to ask for are on your job offer.',
 lead:'Go to the address on your job offer. Ask for the manager named on it.',
 body:['Is nobody expecting you? Do not leave the building. Stay there and call the number on your job offer.','Nobody answers that number either? Message your CHI team right away. Tell them the address you are standing at.','Do not go home and wait. Someone can help you while you are still there.','Got a correction letter? Print it and carry it with your DS-2019.','Your first workday is when you have arrived, checked in, and your paperwork is done, not just the date printed on the form.','On shift, keep your phone away, arrive on time, and ask your manager the question directly. A phone out on the floor can get you sent home.','When the clocks change, check the local time the night before so you are not late.'],
 need:['Your job offer','The phone number of your employer'],
 act:{label:'I am there and nobody is expecting me', kind:'team'},
 w:{trigger:'Tile opened, or escalation tapped', fires:'Nothing automatic on view', captures:'Location and employer if escalated', notify:'Coordinator, marked urgent, on escalation only', log:'Case row opened only if escalated', status:'live'}},
{s:'arr', q:'My housing when I land', sub:'Is it what I was promised, is it safe', r:'File', mo:['intervention','Intervention Required with the photos attached.'], hz:1, ic:'housecrack', k:'housing house bad dirty unsafe unlivable mold broken no bed promised different arrive land first deposit photos',
 you:"Your placement is <b>{employer|your employer}</b> in <b>{location|your town}</b>.[[ Housing status: <b>{housingStatus}</b>.]]",
 lead:"Take dated photos before you move anything. Is it wrong or unsafe? File a housing report. Unsafe right now? Message my CHI team.",
 body:["CHI contacts the housing provider and your employer.","Keep the place clean if you want the deposit back. CHI cannot get a deposit back for dirt, damage, or leaving early.","Approved address on file: <b>{housingAddress|omit}</b>."],
 need:["Dated photos","The address","How many people live there","What you were promised"],
 act:{label:'File a housing report', kind:'form'},
 w:{trigger:'Form submitted', fires:'Acknowledgment to participant, no promise of outcome', captures:'Photos, address, occupancy, what was promised', notify:'Coordinator immediately, employer contact drafted', log:'Case row, category Housing', status:'live', note:'Housing Safety and Welfare Check form is already live. Point the tile at it rather than writing a new one.'}},
{s:'arr', q:'How do I get my I-94', sub:'I-94, entry record', r:'Answer', ic:'printer', k:'i94 i-94 entry record arrival departure cbp free most recent never pay apply admission number',
 you:"Use your name exactly as it is in your passport.[[ Your landing date is <b>{arrivalF}</b>.]]",
 lead:"Do this before onboarding. It is free at https://i94.cbp.dhs.gov/search/recent-search . Choose Get Most Recent I-94. Never choose Apply for I-94. That one charges you.",
 body:["Open https://i94.cbp.dhs.gov and click Get Most Recent I-94/I-95 only.","Camera path: Acknowledge, then Capture Document, then a photo of the full passport page, including the lines at the bottom. Or type the passport data exactly.","Download the PDF. Email it to yourself and to <b>{employer|your employer}</b>. The Admission Number is what payroll needs.","No record? Try your names in the other order. Check the number 0 against the letter O. A library can print it if you have no printer.","You need it for Social Security and for the I-9."],
 need:["Your passport number","Your date of birth","Your name as in your passport"],
 act:{label:'Send me the I-94 instructions', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Get I-94 template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'live', note:'Template exists and is complete.'}},
{s:'arr', q:'How do I validate my SEVIS record', sub:'SEVIS validation, address in SEVIS', r:'Answer', mo:['sevis','The MO team completes the SEVIS entry. Field staff enters it in the portal first, then the SEVIS template tells MO to complete it.'], ic:'pincheck', k:'sevis validate validation activate address registration 3 days activation status rejected room number unit apartment number accommodation type no us phone not active approved',
 you:"Hi <b>{firstName|there}</b>. Validate by <b>{sevisDueF|within 3 days of landing}</b>.[[ You landed <b>{arrivalF}</b>.]][[ Status now: <b>{sevisStatus}</b>.]][[ Validated on <b>{sevisValidationDate}</b>.]]",
 lead:"Validate at wt.chinet.org within 3 days of arrival. Miss it and the programme can be cancelled.",
 body:["Already validated? You are done. Keep the date.","Not yet? Enter your full U.S. address, with the room or unit number. No P.O. box. Choose Apartment if the building has units. Enter your employer.","No U.S. phone yet? Use your employer's number.","Validated but not active? That usually takes a few working days, and longer over a weekend.","Until it is validated, do not go to the Social Security office. You may start the online application earlier.","After CHI validates it, wait for the activation email. That usually takes 3 to 7 days. Then go to Social Security.","Address on file: <b>{housingAddress|omit}</b>."],
 clock:{l:'This has a legal clock', t:'Validate within 3 days of arrival. The visa activation email usually follows 3 to 7 days later.'},
 need:["Full address and unit","City, state, and ZIP"],
 act:{label:'Send my address for SEVIS', kind:'form'},
 w:{trigger:'Form submitted', fires:'SEVIS validation confirmation once processed', captures:'Full address with unit', notify:'Coordinator daily digest', log:'Sevis Validation Date written to the roster', status:'build', note:'Roster already carries Sevis Validation Date and Sevis Status Description. Nothing currently watches an unvalidated record past day 20.'}},
{s:'arr', q:'How do I apply for my Social Security Number', sub:'SSN, social security card', r:'Answer', ic:'card', k:'ssn social security number card apply receipt appointment office validated sevis activation ssa locator has seguridad social ss card appointment site not working walk in ue id consular signature',
 you:"Apply after the visa activation email. The latest useful date is <b>{ssnBy|before you leave}</b>.",
 youYes:"You already have a Social Security number on file. It is good for life. Do not apply again. Give the number to <b>{employer|your employer}</b> if they still need it.",
 youNo:"Apply after the visa activation email. That is usually 3 to 7 days after SEVIS validation[[ on <b>{sevisValidationDate}</b>]]. The latest useful date is <b>{ssnBy|before you leave}</b>.",
 lead:"The activation email is the signal to go to the office. You can work with the receipt before the card arrives.",
 body:["You may already have started the online application and booked a time about 7 business days after you land. Do not attend that appointment until the activation email arrives.","Bring the originals: passport and J-1 visa, DS-2019, I-94, job offer, sponsor letter, and your Online Control Number if you have one.","Ask the card to be mailed to your housing, not to your employer. Then give the number to <b>{employer|your employer}</b>.","Nearest office for <b>{employer|your employer}</b> in <b>{location|your town}</b>: <b>{ssaOfficeName|omit}</b>.","Office address: <b>{ssaOfficeAddress|omit}</b>.","Office phone: <b>{ssaOfficePhone|omit}</b>.","No office on file? Find one at ssa.gov/locator.","The card usually arrives in 7 to 14 business days. Keep the receipt.","{plattsburghNote|omit}"],
 clock:{l:'This has a deadline', t:'Apply at least 45 days before your DS-2019 end date, or the card will not arrive in time.'},
 need:["Passport and J-1 visa","DS-2019","I-94","Job offer","Sponsor letter"],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'The receipt is deliberately not collected. CHI does not chase cards, so a receipt upload would be a form that creates work and answers nothing. The participant keeps it for their employer. Highest message volume item on the arrival board, and the whole of it is the order of the four steps, which is why this is an Answer and not a form.'}},
{s:'arr', q:'How do I fill in my employment paperwork', sub:'I-9, W-4, first day forms', r:'Answer', ic:'formsign', k:'employment paperwork i9 i-9 w4 w-4 forms fill in tax withholding first day hire onboarding nonresident nra exempt nj-w4 it-2104 sprintax direct deposit',
 you:"<b>{employer|Your employer}</b> in <b>{location|your town}</b> hands you the forms on day one.",
 lead:"Bring your passport, your DS-2019, and your printed I-94. Ask before you guess.",
 body:["On the I-9, use your passport spelling. You are a noncitizen authorized to work until <b>{dsEndF|your DS end date}</b>. Use the I-94 Admission Number, or your passport number and country. No Social Security number yet? Ask your employer first. You can enter 999-99-9999. Bring your passport, your I-94, and the original DS-2019.","On the W-4, Step 1 is Single. Skip Steps 2 and 3. In Step 4(c), write Nonresident Alien. Never write Exempt, even if payroll asks.","State forms, if they hand you one: NJ-W4, NY IT-2104, VT W-4VT, DC D-4, VA-4, or MD MW507. Choose Single and allowances 0.","Direct deposit needs a U.S. routing number, 9 digits, and your account number. Check both twice.","If payroll insists on Exempt, show them this page and Message my CHI team. Later tax filing is at https://www.sprintax.com . Do not use TurboTax.","Ask for copies of what you signed."],
 need:["Passport","DS-2019","I-94","Social Security receipt, if you have one"],
 act:{label:'Send me the paperwork guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped, and on placement', fires:'Employment Paperwork Guide template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'live', note:'Template already exists. The W-4 nonresident point is what prevents the FICA problem three tiles later, so the two should reference each other.'}},
{s:'arr', q:'How do I get a US phone number', sub:'SIM card, prepaid, keeping WhatsApp', r:'Answer', ic:'phone', k:'phone number sim card prepaid mobile cell service plan contract whatsapp esim unlocked tally us number',
 you:'Once you have a number, send it to your CHI team. Right now the only way we can reach you is your email, <b>{emailMask}</b>.',
 lead:'Buy a prepaid SIM card. You do not need a Social Security number for it.',
 body:['Prepaid means you pay first, then use it. No contract. No credit check.','You can buy one on your first day, at a phone shop or a large supermarket. Take your passport.','Do not sign a monthly contract in your first weeks. Contracts need a Social Security number and a credit history you do not have yet. They also last longer than your programme.','Your phone must be unlocked. A phone locked to your home network will not take a US SIM card. Unlock it before you leave home. An eSIM is fine if the phone is unlocked.','The same day you get your new number, send it to your employer and to CHI. The form is https://tally.so/r/GxQbZQ . Include your Student ID <b>{sid|your Student ID}</b>. WhatsApp still works until that number is on file.','That number is how anyone reaches you in an emergency. Do not leave it until next week.','Keep your home number on WhatsApp if you can. Then your family still reaches you on the same account.'],
 need:['Your passport','A phone that is unlocked'],
 act:{label:'Send my CHI team my US number', kind:'form'},
 w:{trigger:'Form submitted', fires:'Confirmation to the participant', captures:'New US number', notify:'Nobody', log:'WhatsApp column updated on the roster', status:'build', note:'Small tile, real payoff. Participants change numbers and the roster keeps the old one, which is how people become unreachable and end up as an Unresponsive Participant email.'}},
{s:'arr', q:'How do I open a US bank account', sub:'Bank account, direct deposit', r:'Answer', ic:'bank', k:'bank account open money debit card direct deposit branch savings checking cash revolut paypal 2FA',
 you:"Take a letter from <b>{employer|your employer}</b>, your passport, your DS-2019, and your address[[ <b>{housingAddress}</b>]].",
 lead:"Revolut and PayPal do not work for U.S. payroll. Use a U.S. bank account.",
 body:["Open a U.S. account soon after you arrive. Take your passport and your DS-2019. Bank of America and Wells Fargo are common nationwide options. Confirm what is near <b>{employerCity|your town}</b>.","Tell the bank you are traveling so they do not freeze the card. Put security codes on your email, not only on a U.S. phone, so you can log in from home. Never send those codes to anyone.","Never accept cash wages except tips. You can send money home with Wise or your home bank.","Revolut and PayPal do not work for U.S. payroll.","Did a branch say no? Try another. Then Message my CHI team."],
 need:["Passport","DS-2019","Your address","A letter from your employer"],
 act:{label:'Ask my CHI team which bank is nearest', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Which branches open accounts for J-1 participants varies by host city. Content should be written per area and shown from Location Name on the roster.'}},
{s:'arr', q:'How do I get to work', sub:'Transport, bus, bikes, walking', r:'Answer', ic:'bicycle', k:'transport bus bike walk get to work travel commute jitney train scooter helmet bus late shuttle pickup late driver gas fee transport fee paid for waiting',
 you:"You work at <b>{employer|your workplace}</b> in <b>{location|your town}</b>[[ / <b>{employerCity}</b>]].",
 lead:"Ask how other people in your housing get to work. Small towns often have few buses.",
 body:["Check the last bus before a late shift.","Employer bus late? Note the time and tell your manager the same day. Unsafe driving? Tell your coordinator.","A transport fee should match what you signed. Extra cash requests go to your coordinator.","On a bike or a scooter: wear a helmet, follow the traffic laws, use lights, and stay sober. Tell CHI after any accident."],
 need:["How you plan to get there"],
 act:{label:'Ask my CHI team about my area', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Answer varies by location. Content should be written per host city and shown from Location Name on the roster.'}},
{s:'arr', q:'I need casino fingerprinting', sub:'Fingerprinting, GBA, casino badge', r:'Answer', ic:'finger', k:'casino licence license fingerprint gba badge dge registration',
 you:'You are placed with <b>{employer}</b> in <b>{location}</b>. Is that a casino? Then you cannot start on the floor until your fingerprinting is cleared.',
 lead:'Working in a casino? You cannot start on the floor until your fingerprinting is done and cleared.',
 body:['CHI books the fingerprinting appointment. Not you, and not your employer.','Take your passport, your DS-2019, and your Social Security receipt if you have one.','There is a fee. Most employers take it out of your first pay.','Ask your manager how much it is before you go, so it is not a surprise on your first paycheck.'],
 need:['Passport','DS-2019','The appointment details from your employer'],
 act:{label:'Send me the fingerprinting guide', kind:'template'},
 w:{trigger:'Placement at a casino employer, or tile opened', fires:'Casino Fingerprinting template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'fix', note:'Template exists but jumps from Section 2 to Section 4, uses an all caps headline at weight 800 and off brand colours. Fix before wiring the placement trigger.'}},
{s:'arr', q:'I moved to a new address', sub:'Address change, SEVIS update', r:'File', mo:['sevis','Address has to reach SEVIS within ten days, so this goes to MO the same day it is filed.'], hz:1, ic:'housemove', k:'moved address change new place relocate update sevis housing house move out 10 days',
 you:"You work at <b>{employer|your employer}</b> in <b>{location|your town}</b>.[[ Approved address now: <b>{housingAddress}</b>.]]",
 lead:"Update the address at wt.chinet.org within 10 days of moving. That is a legal requirement.",
 body:["Send the full new address, with the unit, and the move date. SEVIS has to match where you live."],
 clock:{l:'This has a legal clock', t:'Ten days from the day you move.'},
 need:['Full new address with unit number','The date you moved','Who else is living there, if CHI placed them too'],
 act:{label:'Update my address', kind:'form'},
 w:{trigger:'Form submitted', fires:'Address change confirmation', captures:'New address, move date, roommates', notify:'Coordinator, SEVIS update task', log:'Housing Approved Address updated. Case row if the move is within 10 days of arrival', status:'build', note:'No form exists yet. Use the exact required wording about being denied entry, unchanged.'}},
{s:'work', q:'I am not getting enough hours', sub:'Low hours, slow weeks, 32 hours', r:'Team', mo:['intervention','Intervention Required, but only after three short weeks and only with the stubs attached.'], g:'My hours and my pay', ic:'clock', k:'hours not enough slow week 32 hours short cut shifts schedule empty labor day new year holiday drop weather rain smoke shifts cancelled sent home early less hours at will',
 you:"You are on day <b>{day|your programme}</b> of <b>{len|your programme}</b> at <b>{employer|your employer}</b> in <b>{location|your town}</b>.",
 lead:"Your employer agreed to about 32 hours a week as a minimum across the season. Not every single week.",
 body:["Slow weeks happen. If you have had fewer than 3 short weeks, keep your pay stubs.","{hoursHolidayNote}","Three short weeks or more? Message my CHI team. Send the stubs and a photo of the schedule.","Placement window: <b>{placementStart|omit}</b> to <b>{placementEnd|omit}</b>."],
 need:["All of your pay stubs","A photo of the schedule","What your manager replied","Shifts you missed"],
 act:{label:'Send my stubs and schedule', kind:'team'},
 w:{trigger:'Form submitted with at least 3 stubs', fires:'Nothing to the participant automatically', captures:'Stub images, schedule photo, manager response, missed shifts', notify:'Coordinator, subject sortable as Hours, employer, SID', log:'Case row, category Hours. Paycheck Log fed', status:'build', note:'No template written. Paycheck Log sheet exists with zero rows against 42 pay cases: build the feeder before the list.'}},
{s:'work', q:'My pay is wrong', sub:'Wrong hours, wrong rate, deductions', r:'Team', mo:['intervention','Intervention Required once the employer has been contacted and not resolved it.'], g:'My hours and my pay', ic:'billx', k:'pay wrong wage rate deduction short money paid less paycheck incorrect stub direct deposit',
 you:'You are a <b>{job}</b> at <b>{employer}</b> in <b>{location}</b>. Check the rate on your stub against the rate on your job offer before you file.',
 lead:'Upload one pay stub. Your CHI team cannot call an employer about pay without seeing the stub.',
 body:['Choose what is wrong: the hours are short, the rate is wrong, the deductions are too high, or you never received it.','Check the rate against your job offer before you file. Many rate questions turn out to be a training rate for the first weeks, which the offer already said.'],
 need:['One pay stub, photo or PDF','Your job offer','What you think is wrong'],
 act:{label:'Upload my pay stub', kind:'team'},
 w:{trigger:'Stub uploaded. The alert does not fire without it', fires:'Nothing to the participant automatically', captures:'Stub, issue type from a short list, employer, agency, DS dates, weeks in program', notify:'Coordinator, subject line Pay, employer, SID, issue', log:'Case row, category Payroll. Paycheck Log fed', status:'build', note:'Upload gate is the point. An email reply can be words; an upload field cannot.'}},
{s:'work', q:'What tax comes out of my pay', sub:'Tax, tips and overages', g:'My hours and my pay', ic:'formpct', r:'Answer', k:'tax taxes deducted automatic paycheck tips overtime overage overages refund return april w2 fica social security medicare exempt 1040 1040-nr january 31 february sprintax turbotax taxes too high 24 percent federal state w-4 401k retirement transamerica pension letter',
 you:"You are a <b>{job|worker}</b> at <b>{employer|your employer}</b>. Check every pay stub.",
 lead:"Federal, state, and local tax: yes. Social Security and Medicare tax: no.",
 body:["Do you see FICA, OASDI, SS, Med, or FED MED EE? Ask payroll to fix it, then Message my CHI team if they will not.","Your W-2 arrives by January 31. Many copies show up in February. Do not chase a missing W-2 before March 1. File between February 1 and April 15 on Form 1040-NR, using Sprintax at https://www.sprintax.com . Do not use TurboTax. CHI staff are not tax advisors.","Give <b>{employer|your employer}</b> an address that still works then. Check that the Social Security number on the W-2 is yours.","{winterTaxNote|omit}","You should not be in a retirement or 401k plan. Got a letter about one? Ask payroll to remove you, then email your coordinator for the opt-out steps.","Federal and state tax is normal. You can claim the extra back when you file. See How do I claim my tax overages back."],
 need:["Your newest pay stub","Your job offer"],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Tax was 3 percent of orientation questions and always the same three: is it automatic, are tips taxed, do I get an overage back. Putting the FICA line here rather than only in the working board is what catches the wrong deduction in week one instead of week six.'}},
{s:'work', q:'There is Social Security or Medicare on my check', sub:'FICA, OASDI, wrongly deducted tax', r:'File', g:'My hours and my pay', ic:'receiptsearch', k:'fica oasdi medicare social security tax deduction withheld exempt refund overage overages 843 8316',
 you:"At <b>{employer|your employer}</b>, this often shows up for the whole CHI group.",
 lead:"J-1 participants do not pay Social Security or Medicare tax. Show your DS-2019 and ask payroll to fix it.",
 body:["Check the first paycheck. J-1 participants do not pay Social Security or Medicare tax.","Did they not fix it? Message my CHI team and upload one pay stub. Fixing it now is much faster than an IRS claim a year later. Sprintax can help with a later claim. CHI staff are not tax advisors."],
 need:["One pay stub that shows the deduction"],
 act:{label:'Check my stub', kind:'form'},
 w:{trigger:'Form submitted', fires:'FICA outcome template, yes or no', captures:'Stub, employer', notify:'Coordinator, plus automatic check of every participant at that employer', log:'Case row, category Payroll. Employer flagged', status:'build', note:'One submission must trigger a cohort check at that employer. Ocean Casino ran three people; Hard Rock was a Workday setup problem.'}},
{s:'work', q:'I did not get my paycheck', sub:'Missing check, wrong address', r:'Team', g:'My hours and my pay', ic:'envcash', k:'paycheck not received missing lost mail direct deposit address check stub deduction check bounced check declined insufficient funds cant cash my check name wrong on check check never came check mailed missing hours training hours not paid for training worked late not paid homebase tip out last check final check after I leave',
 lead:'Nine times out of ten the check went to an old address.',
 body:['Keep your own record of every shift. A photo of the schedule and your clock-in times is enough.','Check your pay stub every payday. Something missing? Tell your manager or payroll that week, in writing. Training is work. If you were working, you are paid.','Your name on the check does not match your passport, or the bank will not cash it? Ask payroll to reissue it with your passport name.','The check bounced? Do not deposit another check from that employer until you email your coordinator.','Tell your employer your current address in writing, and ask whether the check was posted or held at the workplace.','If it was posted more than ten days ago and never arrived, your CHI team will contact payroll. If the check arrives after you leave, contact your employer directly. Do not mail it to CHI.'],
 need:['The address payroll has for you','The pay period that is missing','Whether you are on direct deposit'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'Address on file, pay period, deposit or check', notify:'Coordinator', log:'Case row, category Payroll', status:'build'}},
{s:'work', q:'My time off was refused', sub:'Days off, holiday, time off request', r:'Answer', g:'My hours and my pay', ic:'calx', k:'time off holiday vacation refused denied days off request leave swap sick call no show doctor note',
 you:'Only <b>{employer}</b> can approve your time off. CHI cannot.',
 lead:'CHI cannot give you time off. Only your employer can.',
 body:['This is not CHI saying no. CHI has no power over your schedule.','Your employer planned the whole season around the people they hired. Summer is their busiest time.','So time off is hardest to get in exactly the weeks you most want it. That is normal, and it is not personal.','Ask at least 2 weeks ahead, in a message, so there is a record. No is a possible answer.','Truly sick? Call your manager at least 2 hours before the shift. The employer may require a U.S. doctor note. Never use a fake note. That can end the job and the programme.','A no-call, no-show can mean immediate termination.','Best trick: offer to swap the shift with someone. Ask your manager to approve the swap. This works far more often than just asking for the day off.'],
 need:[],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'One line answer. Costs 349 replies a season as a conversation.'}},
{s:'work', q:'I have a problem with my manager', sub:'Manager, supervisor, being shouted at', r:'Team', mo:['intervention','Intervention Required for anything that is not ordinary direct feedback.'], g:'My job and the people I work with', ic:'people', k:'manager supervisor boss problem rude shouting unfair treated favouritism conflict tiktok instagram reddit social media post uniform complain group chat phone time theft',
 you:'You are working at <b>{employer}</b> in <b>{location}</b>.',
 lead:'Tell your CHI team what happened. A person will read this, not a machine.',
 body:['Managers in the United States give direct feedback and correct mistakes on the spot. That is normal here and it is not personal.','What is not normal is being shouted at, singled out, threatened or treated differently from American staff. Those are the things to report.','Try the manager first, then HR. Still stuck? Message my CHI team.','Write down the date, what was said and who else was there. Details a week old are much harder to act on.','Do not post about work while you are on shift, in uniform, or in a staff-only area. Do not post negative or untrue claims about pay, housing, managers, or coworkers on TikTok, Instagram, Reddit, or a WhatsApp group. Message your coordinator instead. Breaking this can end your program. Phone use on the floor is time theft.'],
 need:['What happened and when','Who else saw it','Whether it has happened before'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. This tile never auto replies', captures:'Free text, dates, witnesses', notify:'Coordinator immediately', log:'Case row, category Employment', status:'live', note:'Costs 588 replies, the third most expensive topic in the inbox, and no page can settle it. The tile is worth building as intake only.'}},
{s:'work', q:'I have a problem with a coworker', sub:'Someone I work with, not my manager', g:'My job and the people I work with', ic:'talkpair', r:'Answer', k:'coworker colleague workmate teammate problem argument rude lazy not doing their job blaming gossip conflict shouting',
 you:'You are working at <b>{employer}</b> in <b>{location}</b>.',
 lead:'Try to fix it yourself first. Say something within two days, before you get angry.',
 body:['People work differently in different countries. Someone who sounds rude to you may just be direct. Someone who seems slow may have been trained another way.','So not every problem is a problem to report.','Start with: I feel this way when this happens. Can we do this instead?','Do not say: you never restock anything.','Say: I cannot finish my side when the trays are empty. Can we agree who fills them?','Do it soon. Wait two weeks and the talk goes badly. By then you are angry, and they still do not know anything was wrong.','Still stuck after a calm try? Message my CHI team.','Is it about shifts, tips or money? Go to your manager instead. Do not talk to the coworker about that.','Do you also live with this person? Use the housing tile instead. Home problems are handled a different way.'],
 need:['What happened, and when','Have you said anything to them yet','Do you live with them too'],
 act:{label:'This did not work, message my CHI team', kind:'team'},
 w:{trigger:'Tile opened. Nothing sends unless they tap through to the team', fires:'Nothing automatic', captures:'Free text if escalated', notify:'Coordinator only on escalation', log:'Case row, category Communication, only if escalated', status:'build', note:'Split out from the manager tile on purpose. Together they were 65 threads and 588 replies, the third most expensive topic in the inbox, but they are two different problems. A manager problem is a power problem and CHI contacts the employer. A coworker problem is usually a peer problem the participant can solve, and the I statements page from the orientation deck is what solves it. Splitting them means the cheap half stops arriving as a case. Threats, unwanted touching, or being singled out for where they are from is neither of these tiles: that is the unsafe tile and it goes straight to a person.'}},
{s:'work', q:'I was sent home from a shift', sub:'Sent home, suspended, told not to come in', r:'Team', g:'My job and the people I work with', ic:'doorout', k:'sent home shift suspended told not to come back stood down schedule',
 you:'Ask <b>{employer}</b> one question in writing: am I on next week schedule.',
 lead:'Being sent home from one shift is not the same as being fired. Do not assume the worst yet.',
 body:['Ask your manager one question in writing: am I on next week schedule.','Send your CHI team the answer. If you are still on the schedule this is a bad shift, not the end of your job.','If you are not on the schedule, say so straight away. There is a ten day clock and it starts on the day the job ends.','A no-call, no-show is different. That can end the job the same day.'],
 need:['What you were told and by whom','Whether you are on the next schedule','The date'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'What was said, schedule status, date', notify:'Coordinator immediately', log:'Case row, category Employment', status:'build', note:'Frequently mistaken for termination. Separating the two here prevents a 10 Days template firing on someone who still has a job.'}},
{s:'work', q:'I lost my job', sub:'Fired, terminated, let go', r:'Team', mo:['unplacement','Unplacement Notification with the reason, then Mid-Atlantic Offering if a replacement position is found inside the region.'], g:'My job and the people I work with', ic:'bagx', k:'fired terminated lost job let go dismissed sacked no longer employed ten days notice sent home write up final warning suspended attendance points call out no call no show safety warning',
 you:"You are on day <b>{day|your programme}</b> of <b>{len|your programme}</b>. Your programme ends <b>{dsEndF}</b>. Tell <b>{coordinator|your CHI team}</b> today.",
 lead:"Message my CHI team today. Do not start a new job until CHI approves it in writing. A no-call no-show hurts your status.",
 body:["You have 10 days to find a new job and get it approved by CHI. Tell your coordinator today, even if you already have a second job.","US seasonal jobs are at-will. Hours change with weather and business. Be in uniform and ready 10 minutes before your shift. Sick or late? Tell your manager at least 2 hours before. A no-call no-show can end the job the same day.","Never miss a shift without calling in. Never leave before your manager checks you out. Keep your phone away at your station. Phone use on the floor or in training is time theft. Follow the cash-handling rules exactly. Use a meal benefit only as your job description says.","Your supervisor may be 18 to 21. Follow instructions with respect. Saying that is not my job reads as unprofessional. The first 2 to 3 weeks often feel hard. That is normal.","Bring the date and what you were told.","When you leave with CHI approval, give at least one week of written notice when you can."],
 clock:{l:'This has a legal clock', t:'Ten days from the last day of work.'},
 need:["The end date","What you were told","Anything in writing"],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'10 Days template', captures:'Last day, reason given, documents', notify:'Coordinator and manager immediately', log:'Case row, category Employment, severity High. Termination Tracker fed', status:'fix', note:'10 Days template exists. Termination Tracker sheet has zero rows. Do not fire this template on someone who was only sent home from one shift.'}},
{s:'work', q:'How do I get a second job approved', sub:'Approval, vetting, before my first shift', g:'Adding or changing my job', ic:'twobags', r:'File', k:'second job extra work another job additional employment more hours approved approval vetting authorised authorized side job workers comp verbal written first shift overnight valet driving delivery warehouse blood nails barber tattoo find second job where to apply who is hiring job leads reference resume tips declared meal badge unauthorized babysitter uber lifeguard casino dealer door to door 1099 childcare eldercare prohibited',
 you:"Your main job is <b>{job|your job}</b> at <b>{employer|your employer}</b>.[[ Second job on file: <b>{secondJobHost}</b>.]]",
 lead:"A second or additional job needs written CHI approval before your first shift. A verbal OK from an employer is not approval.",
 body:["Use the Additional Employment form in the portal. You and the new employer both complete it. That form is the approval route.","Attach a current business license and the workers compensation certificate, with the policy number, the dates, and the insurer.","The job must be seasonal hospitality or tourism, and it must not conflict with <b>{employer|your main job}</b> or <b>{job|your main role}</b>.","CHI cannot approve these jobs. Ask your coordinator before you accept if you are unsure. Private home help such as childcare or eldercare. Pedicab. Any driving or delivery job that needs a driver's license, including Uber, Lyft, or DoorDash. Clinical patient contact. Adult entertainment. Most overnight work from 10pm to 6am. Commission-only or buy-your-own-inventory sales. Gambling jobs that take wagers, such as a casino dealer. warehouse, factory, construction, or agriculture. A staffing firm that places you somewhere else. A mall kiosk. Door to door. Independent contractor or 1099 work. Sole lifeguard without a supervisor, valet, and jobs that may touch blood or bodily fluids, including nails, barber, tattoo, or vet tech.","Look for places near your housing, with hours that never overlap your main job.","Do not start until CHI emails you an approval. Working before that approval is unauthorized work. Message my CHI team with the packet.","Did you already work there? Say so. Your main job always comes first.","A monthly evaluation is required for the second job too."],
 need:["Legal name and address","Manager","Job title, pay, and hours","Have you already started?"],
 act:{label:'Send my second job for approval', kind:'form'},
 w:{trigger:'Form submitted', fires:'Second Job template to the participant, plus a vetting request to the new employer for the workers compensation certificate', captures:'Employer legal name, address, manager, rate, hours, start date, already started yes or no', notify:'Coordinator. Urgent flag when already started is yes, because that is unauthorised employment and the clock is already running', log:'Second Job Host Business written to the roster. Case row, category Employment. Monthly evaluation obligation added', status:'live', note:'Costs 599 replies, the second most expensive topic in the whole inbox, and 106 of 494 participants have one. Template exists. Two things to get right. The already started question is the whole point of the tile: people find the job and then tell you, so the form has to catch that rather than assume the right order. And the workers compensation certificate is what stalls every one of these, so the vetting request should go to the employer the moment the form lands, not after a coordinator reads it.'}},
{s:'work', q:'My casino fingerprinting', sub:'Not cleared yet, or needed for a new job', g:'Adding or changing my job', ic:'finger', r:'Answer', k:'casino licence license badge fingerprint gba dge registration not issued waiting second casino job renewal lost badge fee deducted cannot start floor',
 you:'You are a <b>{job}</b> at <b>{employer}</b> in <b>{location}</b>, on day <b>{day}</b> of <b>{len}</b>.',
 lead:'CHI books casino fingerprinting. Ask your coordinator where the appointment is. Your employer is told when it clears.',
 body:['CHI books the fingerprinting. Not you, and not your employer.','Go and ask your coordinator where it is. That is the fastest answer you can get.','Are you being kept off the schedule while you wait? That is lost hours and lost money.','Write down every week you were free to work and got no shifts. If this goes past two weeks, send that list to your CHI team.','Do you want a second job at another casino? It needs its own fingerprinting. The one you already have does not move with you.','Did you lose the badge or card your employer gave you? Tell them the same day. Do not wait.','There is a fee. Most employers take it out of your pay. Ask how much, and which week, so it is not a shock.'],
 need:['The date you were fingerprinted','What your manager has told you','The weeks you were free but got no shifts'],
 act:{label:'Send me the fingerprinting guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Casino Fingerprinting template', captures:'Nothing', notify:'Coordinator only if lost hours are reported', log:'Send logged against SID', status:'fix', note:'Second copy of the arrival tile, worded for the middle of the programme where the question changes from how do I get it to where is it. CHI and the participants both say fingerprinting, not licence, so the tiles say that too. Same template behind both, and it still jumps from Section 2 to Section 4, uses an all caps headline at weight 800 and off brand colours. The lost hours line is the part that matters: fingerprinting stuck in processing shows up as an hours complaint weeks later and nobody connects the two.'}},
{s:'work', q:'Can I change to a different employer', sub:'Job change, new employer, resign', r:'File', mo:['placement','Placement Update, then SEVIS Date Update if the dates move with the new employer.'], g:'Adding or changing my job', ic:'swap', k:'change job new employer quit resign different job transfer leave 30 days one week notice workers comp walk out approve leave my job not allowed to quit move my sponsorship to my second job',
 you:"You are on day <b>{day|your programme}</b>. You need 30 days at <b>{employer|your current employer}</b> before a change.",
 lead:"Work at least 30 days first. CHI must approve the new job in writing. Do not walk out of your job. Never stop going to work until CHI emails you an approval for the new job. Give at least one week of written notice.",
 body:["You need 30 days already worked, your Social Security number given to the current employer, a new offer, workers compensation, and a yes from CHI.","Feeling stressed, uncomfortable, or tired is not a reason for a job change. If a health condition stops you from doing the job, you need a written diagnosis from a U.S. doctor before CHI can look at a change. Another entry-level job is often no easier. CHI may advise you to go home for your safety.","Ask for the workers compensation certificate first. That is what delays most cases.","Use the job change form: https://tally.so/r/aQyZxb"],
 clock:{l:'This has a clock', t:'If you leave a job with nothing approved, you have ten days to be placed or your program ends.'},
 need:["The new offer","Workers compensation certificate","30 days already worked","Notice not given yet"],
 act:{label:'Start a job change', kind:'form', url:'tally.so/r/aQyZxb'},
 w:{trigger:'Form submitted', fires:'Job Change template with the document checklist', captures:'New employer, offer, workers comp certificate, notice date', notify:'Coordinator. Chase scheduled at 3 and 7 days for missing documents', log:'Job Changes sheet fed. Case row, category Employment', status:'fix', note:'Form live at tally.so/r/aQyZxb. Job Changes sheet has zero rows against 62 job change cases. Template merge field is the square bracket style, matching the script.'}},
{s:'work', q:'Can I make my second job my main job', sub:'Swap primary and secondary', r:'File', mo:['sevis','SEVIS swap only. No vetting, no new placement record, because that employer is already approved.'], g:'Adding or changing my job', ic:'starbag', k:'second job primary main swap switch make primary secondary hours',
 you:'Your current main job is <b>{job}</b> at <b>{employer}</b>. This is a swap, not a new second job.',
 lead:'This is the simplest of the three job changes and the one filed wrong most often.',
 body:['Your second employer is already approved, so there is nothing to vet. No new workers compensation certificate, and no new fingerprinting.','What is needed is notice to your current main employer, written confirmation that the second employer will give you full hours, and the SEVIS swap done by CHI.','Say clearly that this is a swap, not a new second job. Filing it as a second job sends it down the wrong path.'],
 need:['Written confirmation of full hours from the second employer','Your notice date at the current main job'],
 act:{label:'Swap my primary job', kind:'form'},
 w:{trigger:'Form submitted', fires:'Primary swap confirmation', captures:'Second employer, confirmed hours, notice date', notify:'Coordinator, SEVIS swap task', log:'Case row, category Employment', status:'build', note:'No template and no form yet. Aleksandrina Gerasimova SID 60617 in August 2026 had a primary swap processed as a second job. That misfile is why this tile exists separately.'}},
{s:'work', q:'Something else about my job', sub:'Anything not on this board', g:'Anything else', ic:'askbubble', r:'Team', k:'other something else not listed different question anything else help job work monthly evaluation report check-in cultural who to ask routing employer landlord img holiday juneteenth labor day independence closure daylight saving eid hanukkah lunar new year',
 you:'You are working as a <b>{job}</b> at <b>{employer}</b> in <b>{location}</b>, on day <b>{day}</b> of <b>{len}</b>.',
 lead:'If your question is about your job and it is not on this board, write it here.',
 body:['Tell your CHI team what is happening in your own words. It does not have to be written well and you do not need to know what to call it.','Say what has already happened, what you have already tried, and what you want to change. Those three things are what let a person actually help rather than write back asking questions.','Who should I ask? Employer or HR: schedule, hours, pay, onboarding, uniform, and a coworker problem. Landlord: rent, keys, utilities, deposits, and house rules. CHI does not negotiate your rent. Message my CHI team for SEVIS, a second job, an address, a monthly evaluation, a travel signature, or a pay problem you already raised with your manager. Insurance card, doctors, and claims: the Envisage Student Zone, or IMG at 1-855-731-9445. If you are in danger, open the unsafe tile. For counseling, open the homesick tile.','U.S. federal holidays close CHI, many banks, post offices, and Social Security. Plan banking and a Social Security visit for a normal weekday. Hospitality shifts are often long on a holiday weekend.','A person reads this. Nothing automatic is sent.'],
 need:['What is happening','What you have already tried','What you want to happen next'],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. This tile never auto replies', captures:'Free text, plus SID, employer, agency, DS dates and day in programme attached automatically', notify:'Coordinator', log:'Case row, category left blank for the coordinator to set', status:'build', note:'The standing rule is fail toward a human, and this is where that happens on the busiest board. It matters that it carries the participant context automatically: in the vacation window, 7 of 43 threads were people who only said hello and never stated their question, and several of those went to another coordinator instead. A free text box with the SID already attached turns that into something answerable on the first reply.'}},
{s:'life', q:'I was in an accident', sub:'Injured at work, car accident, incident', g:'Medical and safety', ic:'warntri', r:'Team', k:'accident injured hurt at work injury workers compensation comp car crash fell burn cut incident report claim 911 chi emergency deductible student zone',
 you:"You work at <b>{employer|your workplace}</b> in <b>{location|your town}</b>. Your cover runs <b>{insStartF}</b> to <b>{dsEndF}</b>.",
 lead:"Is it serious? Call 911. Then call CHI at 1-800-432-4643, ext. 0. That line is open 24/7. Then Message my CHI team the same day.",
 body:["Hurt at work? Tell your manager the same day. The clinic bills workers compensation, not your travel insurance. Say that it happened at work.","Hurt away from work? Use your IMG and UnitedHealthcare plan. Keep every bill. File one claim for each injury in the Envisage Student Zone.","An emergency room visit under the travel plan still has a 350 dollar deductible each visit.","Photograph what caused it. Write down the names of people who saw it."],
 need:["What happened, where, and when","Did it happen at work?","Who saw it","The bills"],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic. Medical Help template only if they also select that they need care', captures:'What happened, date, at work yes or no, witnesses, bills', notify:'Coordinator and manager immediately. Marked time sensitive', log:'Case row, category Wellbeing, Safety Incident. Hospitalised and DoS Notified columns set where they apply', status:'build', note:'Split out from sick or hurt because the money and the paperwork run down two different routes. At work means workers compensation and an employer report. Away from work means the travel insurance. Getting that wrong at the clinic is what produces a bill nobody will pay. There were 16 safety incidents and 24 sick or injured cases this season and no tile separated them.'}},
{s:'life', q:'I am sick or I am hurt', sub:'Doctor, hospital, insurance, Teladoc', r:'Answer', mo:['intervention','Intervention Required only when hospitalised is selected. Everything else stays with the coordinator.'], g:'Medical and safety', ic:'heartpulse', k:'sick hurt ill injured doctor hospital medical insurance teladoc urgent care pain walk-in img 18008352362 46208 er 350 x-ray xray fracture broken sprain hospital bill bill came collections they dont take international insurance prescription expensive pharmacy dentist tooth filling hurt at work',
 you:"Hi <b>{firstName|there}</b>. Your insurance is UHC Options PPO through IMG and runs from <b>{insStartF|7 days before your DS start}</b> to <b>{dsEndF|your DS end date}</b>.",
 lead:"Is it an emergency? Call 911. Is it not an emergency? Do not start at the emergency room. Each emergency room visit has a 350 dollar deductible.",
 body:["Start with Teladoc. It is free, day and night, in the USA only. Use the app or call 1-800-835-2362. If they ask for a ZIP code, use 46208.","Do you need to be seen in person? Prefer a walk-in clinic. The copay is 0 dollars. Urgent care has a 25 dollar copay. Stay in the UnitedHealthcare network. Always show your insurance card.","The plan is UnitedHealthcare Options PPO, administered by IMG. On 2026 materials the plan number is EGNPK00563298. Does a clinic refuse the card? Say that, then call IMG at 1-855-731-9445.","Too sick for <b>{employer|work}</b>? Call your manager at least 2 hours before the shift. Do not only send a text.","Pay the pharmacy first. Keep the receipt and the label on the medicine. Send a claim in the Envisage Student Zone.","Hurt at work? Tell your manager the same day, before the shift ends.","Not an emergency? Go to urgent care, not the emergency room.","A clinic or hospital bill? Do not pay it yourself. Email it to your coordinator so it can go on your claim.","Feeling stressed or tired is not a medical reason to change jobs. If a health condition stops you from doing the work, you need a written diagnosis from a U.S. doctor before CHI can look at a change.","A clinic says it does not take your insurance? Show the card again and ask them to bill IMG. If they still refuse, call the number on the card.","Dental is not covered. Call two or three offices for a price first."],
 need:["Your insurance card","Bills","Receipts"],
 act:{label:'Send me the medical guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Medical Help template, with offices version if the employer matches', captures:'Nothing', notify:'Nobody on view. Coordinator if hospitalised is selected', log:'Send logged. Case row if hospitalised', status:'fix', note:'Template still contains unfilled Hospital List and Urgent Care List placeholders and currently auto sends overnight. Fix the placeholders before this tile goes live.'}},
{s:'life', q:'I want to see a doctor', sub:'Teladoc, urgent care, appointments', g:'Medical and safety', ic:'doctor', r:'Answer', k:'doctor appointment teladoc urgent care clinic gp family doctor prescription pharmacy medicine see someone book img 46208 walk-in claim student zone',
 you:"You are covered from <b>{insStartF}</b> to <b>{dsEndF}</b>. Have your policy number ready.",
 lead:"Start with free Teladoc. It works in the USA only, and only after your cover has started.",
 body:["Register at teladoc.com only after your cover starts, and only while you are in the USA. Use the name on your ID card. ZIP code 46208. Do not enter a promo code. The provider shows as Exchange - General Medical.","Phone: 1-800-835-2362. It treats colds, flu, rash, sinus trouble, allergies, and similar problems that are not emergencies. It is free, day and night.","Mental health is not on Teladoc. Use DialCare for that.","In person, search for UnitedHealthcare providers. Prefer a walk-in clinic at 0 dollars, or urgent care at 25 dollars. Use the emergency room only for a real emergency. The deductible is 350 dollars. The Healthcare Guide also lists wider bill ranges: Teladoc about 0 to 250 dollars, urgent care about 25 to 275 dollars, and an emergency room about 350 to 600 dollars. Not covered: routine dental, vision, a problem you had before the plan, medicine you can buy without a prescription, and extreme sports.","After that, the deductible for one illness or injury is 250 dollars. Then the plan pays eligible costs.","For medicine, pay the pharmacy, keep the receipt and the label, and send a Student Zone claim. Use one form for each illness or injury.","Claims go to IMG Claims, P.O. Box 240429, Apple Valley, MN 55124, or customercare@imglobal.com, or wherever the Student Zone sends you. Send proof within about 180 days.","IMG help: 1-855-731-9445, or +1 317-927-6806, or CustomerCare@IMGlobal.com."],
 need:["Your card and policy number","Your passport","A list of medicine you take now"],
 act:{label:'Send me the medical guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Medical Help template, with offices version if the employer matches', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'fix', note:'Separate from sick or hurt on purpose. That tile is triage, this one is mechanics: how you actually get seen and what it costs. Same template behind both, and it still carries unfilled Hospital List and Urgent Care List placeholders and auto sends overnight. Fix those before either tile goes live, because this is the tile that sends someone to a specific clinic.'}},
{s:'life', q:'I have a toothache', sub:'Dentist, dental cover, tooth pain', g:'Medical and safety', ic:'tooth', r:'Answer', k:'tooth toothache dental dentist teeth wisdom filling extraction cavity gum pain mouth abscess crown traumatic injury not covered vision img',
 you:"Your cover runs <b>{insStartF}</b> to <b>{dsEndF}</b>. Routine dental care and vision care are not covered.",
 lead:"An ordinary toothache, a filling, a cleaning, or wisdom teeth: you pay. Do not use the emergency room for an ordinary toothache.",
 body:["A tooth broken in an accident, and treated at a hospital, may be covered. The deductible still applies. Call IMG at 1-855-731-9445 before you book if you are not sure. Or use the accident tile.","See a dentist at home before you fly. In the US, call two or three offices for a price before you agree. Bring an extra pair of glasses. Routine dental and vision care are not covered.","Ask CHI for a lower-cost clinic near <b>{location|you}</b>."],
 need:["Your insurance card","Was it an accident?","How many days it has hurt"],
 act:{label:'Ask my CHI team what is near me', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Small tile, real money. Dental came up as its own case type this season and the medical template says nothing about it, so every one of these arrives as a message. The answer is mostly the same everywhere: it is not covered, do not use an emergency room, ask the price first. The only part that varies is the nearest low cost clinic, which is the same per host city gap as the unfilled Hospital List and Urgent Care List placeholders already sitting in the medical template.'}},
{s:'life', q:'Where do I find my insurance card', sub:'Insurance card, policy number, cover dates', g:'Medical and safety', ic:'inscard', r:'Answer', k:'insurance card policy number health cover proof portal download find lost medical coverage envisage img unitedhealthcare egnpk student zone wallet visa letter 46208',
 you:"Hi <b>{firstName|there}</b>. You are covered from <b>{insStartF}</b> to <b>{dsEndF}</b>. The dates on the card should match.",
 lead:"Download the card from the Envisage Student Zone before you fly. Keep it on your phone and on paper.",
 body:["Open https://www.envisageglobalinsurance.com/student-zone/chi-img/ and search by the email on your application, plus your date of birth. The first person icon is the insurance card. Also save the visa letter.","Add the card to Apple Wallet or Google Wallet, print one copy, and email yourself the PDF.","The plan is UnitedHealthcare Options PPO, administered by IMG. On 2026 CHI materials the plan number is EGNPK00563298.","Does a clinic not recognize the card? Say UnitedHealthcare Options PPO, and that IMG is the administrator. Then call 1-855-731-9445. CHI cannot see your medical records or file a claim for you.","Walk-in clinics are 0 dollars. Urgent care is 25 dollars. An emergency room adds a 350 dollar deductible. After that, you usually pay up to 250 dollars for each new illness or injury before IMG pays more.","Teladoc is free in the United States: teladoc.com or 1-800-835-2362. If they ask for a ZIP code, use 46208. DialCare counseling is dialcare.com/verify or 1-855-335-2255.","There is no CHI medical cover after <b>{dsEndF}</b>, during the grace period, or for ordinary travel outside the United States. Buy separate cover if you need it.","Cannot log in? Message my CHI team. The CHI programme portal is wt.chinet.org. The insurance card and the claims live in the Envisage Student Zone."],
 need:["Your Envisage or Student Zone login"],
 act:{label:'Send me my insurance card', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Get Health Insurance Card template', captures:'Nothing', notify:'Nobody', log:'Send logged against SID', status:'live', note:'Template already exists, so this one is ready to wire. It is the enabling tile for accident, sick or hurt and toothache: none of those three go well if the participant cannot produce a policy number. Worth also firing it on arrival rather than waiting to be asked, since the cost of them not having it is a clinic refusing to treat or billing at the uninsured rate.'}},
{s:'life', q:'I feel unsafe or I am being harassed', sub:'Safety, harassment, threats', r:'Team', mo:['intervention','Intervention Required immediately, marked time sensitive.'], g:'Medical and safety', ic:'shieldalert', k:'unsafe harassed harassment threat assault scared danger touch abuse 911 chi emergency alcohol tobacco vape weed marijuana 21 gamble gambling casino scooter helmet passport uber night walk plate extreme sports',
 you:"A person will read this. Your coordinator is <b>{coordinator|your CHI team}</b>.",
 lead:"Are you in danger now? Call 911. Then call CHI at 1-800-432-4643, ext. 0. That line is open 24/7. Then Message my CHI team.",
 body:["You do not need perfect English. You do not need proof.","Threats, unwanted touching, or being blocked from leaving your job or your housing: tell CHI now.","In the US you must be 21 to buy, hold, or use alcohol, tobacco, or vaping products, and to gamble. Marijuana is illegal under federal law even where a state allows it. Your J-1 is a federal program, so marijuana use can end your job and your program. Drug or alcohol injuries are not covered by CHI insurance.","Keep your passport and DS-2019 locked at your housing. Do not take your passport to work. It is illegal for an employer or a landlord to keep your passport. Carry a secondary ID.","Wear a helmet on every bike. Scooters are strongly discouraged. If you ride one, wear a helmet. Extreme sports, such as off-trail skiing or ice climbing, are not covered.","Do not walk alone in dark empty areas. Share your live location with someone you trust. Use a licensed taxi, Uber, or Lyft, and photograph the plate. Landing late at night? Stay at a hotel until morning.","Never eat or drink anything a customer or coworker left for you.","DialCare is for counseling later. It is not for immediate danger.","Nothing on this page sends by itself."],
 need:[],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. Never any automatic reply', captures:'Free text only, no required fields', notify:'Coordinator and manager immediately', log:'Case row, category Wellbeing, severity Escalating', status:'live', note:'No form gate, no required fields, no auto reply. 911 stays inside this tile.'}},
{s:'life', q:'I am struggling or homesick', sub:'Homesick, lonely, low, stressed', r:'Team', g:'Medical and safety', ic:'handsheart', k:'homesick struggling sad lonely depressed stressed mental health cry help dialcare 988 wellness verify 18553352255',
 you:"Hi <b>{firstName|there}</b>. A person will read this.",
 lead:"Weeks 3 and 4 are the hardest for many people. It often gets easier in about 10 days.",
 body:["Counseling in your plan is free. Register at dialcare.com/verify, or call DialCare at 1-855-335-2255. The hours are 7am to 10pm in every U.S. time zone, every day, in English or Spanish.","A session is 30 minutes, by video or by phone, with a licensed counselor.","If you are upset, wait about 30 seconds before you answer a message.","DialCare is for counseling. It is not for immediate danger.","Do you need someone right now? Call or text 988. Or Message my CHI team. Your coordinator is <b>{coordinator|your CHI team}</b>."],
 need:[],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing. Never any automatic reply', captures:'Free text only', notify:'Coordinator', log:'Case row, category Wellbeing', status:'live', note:'988 stays inside this tile. No auto reply, no form gate.'}},
{s:'life', q:'I lost my passport or another document', sub:'Lost passport, lost DS-2019, stolen', r:'Team', mo:['custom','No template exists for this. The DS-2019 reprint request goes to MO carrying name, SID, DS Number, agency, program dates, employer, shipping address and the circumstances, and the 75 dollar fee is acknowledged before it is sent.'], g:'My documents and travel', ic:'passportq', k:'lost passport stolen document ds2019 missing police report consulate replace ds-2019 replacement insurance card envisage wallet luggage lost bag baggage case number',
 you:"[[You are in <b>{country}</b>.]] A replacement DS-2019 costs 75 dollars.[[ DS Number <b>{dsNumber}</b>.]]",
 lead:"Get a police report first. Lost your passport? Also call CHI at 1-800-432-4643, ext. 0. That line is open 24/7. Then Message my CHI team.",
 body:["Was it stolen? Get the report number.","Lost or stolen wallet: file a police report and keep the case number.","Lost luggage: keep the baggage claim tag and the file number. Give the airline your housing address.","A visa can only be replaced outside the United States. You can finish the programme and go home. You cannot leave and come back.","Passport and DS-2019 both gone? That is two paths at the same time.","Lost only the insurance card? Download it again from the Envisage Student Zone. A clinic needs it before they treat you."],
 clock:{l:'Do this first', t:'Police report, before anything else.'},
 need:["The police report","What was lost","A shipping address"],
 act:{label:'Report a lost document', kind:'form'},
 w:{trigger:'Form submitted', fires:'Consulate details for the participant Birth Country, plus DS-2019 fee acknowledgment if applicable', captures:'What was lost, police report, shipping address', notify:'Coordinator, main office for DS-2019 reprint, DoS branch if passport or DS-2019', log:'Case row, category Compliance. DoS Notified column set', status:'build', note:'Consulate lookup runs off Birth Country in the roster and must name the real consulate, address, phone and hours. The 75 dollar fee is acknowledged before submission, not after. Open question: what is the DoS reporting window and does it differ by document.'}},
{s:'life', q:'I need a letter or a document from CHI', sub:'Proof of address, DS-2019 copy, letters', r:'Answer', g:'My documents and travel', ic:'letter', k:'letter document proof address copy ds2019 verification employer letter portal',
 you:"Hi <b>{firstName|there}</b>. Your Student ID is <b>{sid}</b>.[[ DS Number <b>{dsNumber}</b>.]]",
 lead:"Your DS-2019 copy and your proof of address are at wt.chinet.org. Download them yourself.",
 body:["Do you need a different letter? Message my CHI team. Say who it is for, what it must say, and the date you need it."],
 need:["Who the letter is for","What it must say","The date you need it"],
 act:{label:'Request a letter', kind:'team'},
 w:{trigger:'Form submitted', fires:'Portal link first. Letter drafted only if the portal does not cover it', captures:'Recipient, purpose, deadline', notify:'Coordinator', log:'Case row, category Communication', status:'build'}},
{s:'life', q:'I cannot get into my CHI portal', sub:'Login, password, wrong email', g:'My documents and travel', ic:'padlock', r:'Team', k:'portal login log in cannot access password forgot reset locked out account email wrong link website sign in cant get in username wt.chinet.org envisage student zone sid student id signature student program id my id number who is my sponsor sponsor letter the form which section I didnt get the email spam link not working',
 you:"Your record is under <b>{emailMask|the email on your application}</b>. Your Student ID is <b>{sid|on your welcome email}</b>.",
 lead:"Your Student ID is how CHI finds you. Put it in every email. The portal is wt.chinet.org. Use the password reset. Do not make a second account.",
 body:["Your sponsor is CHI. Your sponsor letter is in the portal.","Your Student Program ID is on your portal home page. Use it on every CHI form. Your ID is <b>{sid|on your welcome email}</b>.","Never send your password or a login code to anyone, including CHI staff.","Your job offer, your DS-2019, your sponsor letter, and your programme forms live there.","A useful subject line is Work and Travel, then <b>{sid|your Student ID}</b>, then <b>{firstName|your name}</b>, then the topic.","Your insurance card and your claims live in the Envisage Student Zone. The link is on your ID card or your welcome email. That site is not wt.chinet.org.","Check spam, including the promotions folder. Still stuck? Message my CHI team and send the address you tried."],
 need:["The email address you tried","A screenshot of the error"],
 act:{label:'Tell my CHI team I cannot log in', kind:'team'},
 w:{trigger:'Form submitted, or the bar button tapped from any board', fires:'Nothing automatic', captures:'Email address attempted, error message', notify:'Coordinator', log:'Case row, category Portal Access', status:'build', note:'Reachable from the bar on every screen, not only from this board, because twenty three other tiles tell a participant to go to the portal and every one of them fails silently if they cannot get in. Confirm the real reset flow and the portal URL before this goes live, and if a self service reset already exists the action should point straight at it rather than at a person.'}},
{s:'life', q:'My Social Security card has not come', sub:'Applied, but nothing in the post', g:'My documents and travel', ic:'cardwait', r:'File', k:'social security card not received never came missing lost post mail four weeks status check replacement moved address ssn number employer asking ssa office second job w-2c zeros',
 you:"Your programme ends <b>{dsEndF|your end date}</b>. The last useful day for a new card is about <b>{dsEndMinus21|3 weeks before your end date}</b>.",
 youYes:"Your card or number is already marked received. Give the number to every employer, including a second job. You do not need the plastic card.",
 youNo:"Your programme ends <b>{dsEndF|your end date}</b>. The last useful day for a new card is about <b>{dsEndMinus21|3 weeks before your end date}</b>.",
 lead:"Every employer, including a second job, needs your Social Security number before you leave.",
 body:["Have the card? Give the number to every employer today.","The card usually arrives in 7 to 14 business days. Nothing after 14 business days? Go back to the office with your receipt.","The mail goes to the address you gave the Social Security office. In shared housing, put your name on the mailbox.","Did you move? Tell the Social Security office, and update your address with CHI within 10 days.","Office: <b>{ssaOfficeName|omit}</b>.","Office address: <b>{ssaOfficeAddress|omit}</b>.","Office phone: <b>{ssaOfficePhone|omit}</b>.","No office on file? Use ssa.gov/locator.","Check your pay stub. A temporary number or all zeros needs a payroll fix before you leave, or the W-2 can be wrong.","{winterTaxNote|omit}","Keep working. Show the receipt to <b>{employer|your employer}</b>.","Are they cutting your hours because the card is missing? Message my CHI team.","Do not go home without the number."],
 clock:{l:'Chase it before you fly home', t:'Once you leave the United States a missing Social Security number becomes very hard to fix, and you need it to file your tax return next April.'},
 need:["Your receipt","The day you applied","The address you gave Social Security","Your address now"],
 act:{label:'Tell CHI my card has not come', kind:'form'},
 w:{trigger:'Form submitted, and automatically at DS Start plus 45 where Has Social Security Card is still blank', fires:'SSN chase steps template', captures:'Application date, address applied with, current address, whether they have moved', notify:'Coordinator', log:'Case row, category Social Security. Has Social Security Card left blank until confirmed', status:'build', note:'The apply tile is the highest volume item on the arrival board, and this is the half of it that has never had an answer written. CHI does not collect the application receipt, so the trigger cannot wait for one: it has to fire on time alone, forty five days after the start date with the card still blank. Catching a moved address is the single highest value line here, because that is the failure that silently costs the whole number.'}},
{s:'life', q:'Address verification for the bank', sub:'Proof of address, for the bank', g:'My documents and travel', ic:'addressdoc', r:'Answer', k:'address verification proof of address bank account open document letter residence where i live portal download branch',
 you:'You are at <b>{employer}</b> in <b>{location}</b>. The proof of address in your portal uses the housing address CHI has for you. Open it and check that address is right.',
 lead:'It is already in your CHI portal. Download it yourself. You do not need to ask anyone.',
 body:['Banks here want proof that you really live where you say you live.','Your portal has a proof of address document. It has your name and your US address on it.','Print it. Take it with your passport and your DS-2019. Some branches want all three.','Some branches want a second proof too. A pay stub with your address on it works. So does a short letter from your employer.','First, check the address on it. Is it wrong or old? Fix your address with CHI before you go to the bank.','This matters more than the bank. That document uses the address CHI has for you. A wrong address here means a wrong address on the government system too, and that is the bigger problem.','Did a branch say no? Ask them to write down exactly what they will accept. Send that to your CHI team. Branches all ask for different things, and this is nearly always fixable.'],
 need:['Your CHI portal login','Your passport','Your DS-2019'],
 act:{label:'Ask my CHI team', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends. The document is already in the portal', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'live', note:'The portal already holds this alongside the DS-2019 copy, so the tile is a pointer rather than a request. The useful part is the warning: the document is generated from the roster address, so a participant who finds it wrong has just discovered that their SEVIS address is wrong too. That should route them to the address change tile rather than to the bank.'}},
{s:'life', q:'Can I travel inside or outside the United States', sub:'Travel, Canada, cruise, other states', r:'Answer', g:'My documents and travel', ic:'globeplane', k:'travel canada cruise mexico trip vacation outside country other state puerto rico signature entries visa re entry CHIWT img abroad esta etA canada.ca',
 you:"Your programme runs <b>{dsStartF}</b> to <b>{dsEndF}</b>. Be back before <b>{dsEndF}</b>.",
 lead:"Travel inside the United States is fine. Leaving the country needs four steps.",
 body:["One. The Entries line on your visa must say M, not S.","Two. Your return flight must land before <b>{dsEndF|your end date}</b>.","Three. You need a written yes from <b>{employer|your employer}</b>.","Four. Request a travel signature 2 weeks ahead. Email a clear photo of the full DS-2019 page to CHIWT@chinet.org. Include your name, your Student ID <b>{sid}</b>, your employer, and the dates.","Canada, Mexico, and a cruise that stops in another country all count as leaving. Puerto Rico does not, and it needs no travel signature.","Thinking of Canada from <b>{location|your town}</b>? Your J-1 visa does not admit you to Canada. Check the official tool at https://www.canada.ca/en/immigration-refugees-citizenship/services/come-canada-tool-visit.html . A plane and a land crossing can have different answers. You still need a CHI travel signature for the trip.","You cannot re-enter the United States after your DS end date, even to catch a flight home. A return on ESTA as a tourist is not guaranteed, and you cannot work on it.","Your U.S. medical cover, Teladoc, and DialCare are for the USA. Outside the United States, call IMG at 1-855-731-9445 before you go, and buy any extra cover you need."],
 clock:{l:'Before you book anything', t:'Request a travel signature 2 weeks ahead. Without a valid one, the border can refuse to let you back in, even when everything else is correct.'},
 need:["What Entries says","A scan of your DS-2019","A written yes from your employer","Your travel dates"],
 sample:{title:'Email to send to CHIWT@chinet.org', lines:[
   'To: CHIWT@chinet.org',
   'Subject: Travel Signature Request, {name}, SID {sid}',
   'Attach: a clear full page scan of your DS-2019',
   '',
   'Hello CHI Team,',
   '',
   'I am writing to request a travel signature on my DS-2019.',
   '',
   'Full name: {name}',
   'Student Program ID: {sid}',
   'Employer: {employer}, {location}',
   'Programme dates: {dsStartF} to {dsEndF}',
   'Visa type: J-1, Entries M',
   '',
   'Travel destination: [country and city]',
   'Departure date from the United States: [date]',
   'Return date to the United States: [date]',
   '',
   'My employer has approved this time off. A clear scan of my DS-2019 is attached. Please sign it and send it back before my departure date.',
   '',
   'Thank you,',
   '{name}',
   '[your email]',
   '[your WhatsApp number]']},
 act:{label:'Send me the travel guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Travel Outside US template', captures:'Nothing on view', notify:'Signature request goes to CHIWT, not to the coordinator', log:'Send logged against SID', status:'fix', note:'Template content is complete and correct. Two things wrong with it. It has no name merge field at all, so it opens with the literal text Hi followed by a dash. And the sample email inside it is written with blank placeholders the participant has to fill in by hand, when the page already knows their name, SID, employer, location and programme dates. The tile version fills those in, which is the difference between a template and an answer. This tile never reaches the coordinator queue, which is the point of it.'}},
{s:'life', q:'I am being evicted', sub:'Told to leave, notice, back rent', g:'Where I live', ic:'housealert', r:'Team', hz:1, k:'evicted eviction notice told to leave kicked out back rent behind owe landlord removed housing lose my room',
 you:'Your placement is <b>{employer}</b> in <b>{location}</b>. Tell your CHI team today, whatever the notice says.',
 lead:'Tell your CHI team today. Do not wait to see what happens next.',
 body:['A landlord here usually cannot put you out the same day, but the process moves quickly and it is far easier to stop at the start than after a date has passed.','Find out what it is actually about. Most of the time it is unpaid rent, and most of the time that is a deduction that quietly stopped coming out of your pay, or a roommate who did not pay their share.','If it is rent, ask for the exact amount owed and the exact dates it covers, in writing. Then check it against your pay stubs before you agree that you owe it.','If it is a complaint about noise, damage, guests or pests, ask what specifically and by when it has to stop.','Do not sign anything and do not agree to leave until your CHI team has seen the notice.','Photograph the notice, or forward the message, exactly as you received it.','If you share the unit, this affects everyone in it. Tell the others today, because usually they have the same notice coming.','Keep going to work. Losing the job on top of this turns one problem into two, and the job is what pays the rent.'],
 need:['A photo of the notice, or the message you were sent','The amount owed and the dates it covers','Your pay stubs showing the rent deduction','Who else lives in the unit'],
 act:{label:'Message my CHI team now', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic. This tile never auto replies', captures:'Notice image, amount claimed, dates, roommates, whether rent is deducted from pay', notify:'Coordinator and manager immediately, marked time sensitive', log:'Case row, category Housing, severity High. Every other participant at the same address flagged for a check', status:'build', note:'Split out from the housing problem tile because the clock is different. There were six back rent warnings this season, every one of them from a single agency and four of them at the same store. That pattern is the reason the trigger has to check the whole address rather than the one person who wrote in: when one participant is behind on rent at a shared placement, the others usually are too and nobody has told them yet.'}},
{s:'life', q:'There is a problem at my housing', sub:'Repairs, rent, roommates', g:'Where I live', ic:'housetools', r:'Team', hz:1, k:'housing house problem rent roommate landlord repair broken heating water pests noise during program deduction back rent rent warning owe rent move out landlord fine trash fine deposit back housing deposit rent charged after I left landlord wants more money dirty unsafe fight at housing',
 you:"You are with <b>{employer|your employer}</b> in <b>{location|your town}</b>.[[ Housing status: <b>{housingStatus}</b>.]]",
 lead:"Take dated photos. Write to the landlord. Then Message my CHI team.",
 body:["For a repair, keep the written request.","Double rent or a strange deduction? Keep the pay stub and the receipt. CHI does not negotiate your rent.","Rent is due on the day your housing says, even in a slow week. A back-rent warning can take you off the schedule. Talk to your landlord before the due date.","Moving? Update your address in the portal within 10 days. See I moved to a new address.","Leaving employer housing? Move out by the date you are given. Take photos of the room that day. They help get your deposit back.","Charged rent for days after you left? Email your coordinator with your move-out date.","A problem with roommates? Start with: I feel this way when this happens. Can we do this instead? Speak within 2 days. Still stuck after a calm try? Message my CHI team.","Were you told to leave? Use the eviction tile."],
 need:["Photos","What you wrote to the landlord","Proof of rent"],
 act:{label:'Message my CHI team', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'Photos, landlord contact record, rent evidence', notify:'Coordinator', log:'Case row, category Housing. Housing sheet fed', status:'build', note:'Housing sheet exists with zero rows against 26 housing cases. Built and never fed, same as Job Changes and Paycheck Log. Build the feeder before the list.'}},
{s:'end', q:'I want to go home early', sub:'Shorten my program, leave early', r:'File', mo:['shorten','Shorten Program, carrying reason, employer, location, position, first and final day of work, whether the employer was given one week notice, and the departure city and date. Fires on the departure date, and only when the 16 day branch is met.'], ic:'planeback', k:'go home early shorten leave early end program finish early quit go back boarding pass baggage tag finish early last day of work stop working end my contract go back to school university starts classes start family emergency shortn early exit luggage tag proof of return job offer ends before DS contract ends can i work until ds end work until the end extend my program extention grace period 30 days last day to leave missed my flight 15 days',
 you:"Your program ends <b>{dsEndF|on the end date on your DS-2019}</b>. The 30-day grace period starts on your last day of work.[[ It ends <b>{graceEnd}</b>.]] Your coordinator is <b>{coordinator|your CHI team}</b>.",
 lead:"Finishing a few days early to travel is not the same as shortening your program. Tell <b>{employer|your employer}</b> first, then tell us.",
 body:["Finishing work early but leaving the United States by <b>{dsEndF|your DS end date}</b>? Tell <b>{managerName|your manager}</b> in writing at least one week before your last shift. Then email your coordinator with that last day.","Leaving the United States early? Tell your employer in writing first, with one week's notice. Then fill in the shorten form once: https://tally.so/r/pbLbZP. If your dates change, email your coordinator. Do not send a second form.","After you fly, email a photo of your boarding pass or luggage tag. We cannot close your program without it.","Your job offer ends before <b>{dsEndF|your DS end date}</b>? You may keep working until that date if <b>{employer|your employer}</b> wants you to.","Stopping more than 15 days before <b>{dsEndF|your DS end date}</b>? Submit the shorten form after you tell your employer. Finishing 15 days or fewer early? CHI may not need a SEVIS shorten. Still tell your employer and your coordinator, and send the boarding-pass photo.","The 30-day grace period starts on your last day of work. You cannot work in it.","Leave your bank account open until your last paycheck has arrived. If that check comes after you leave, contact your employer directly. Do not mail it to CHI. See How do I get my final paycheck.","Use a real last day of work and a real flight date.","Leaving 16 or more days early? Keep that proof ready."],
 need:["Your last day of work","Your flight date","Your itinerary","Did you tell your employer?"],
 sample:{title:'Email you can send your employer', lines:[
   'Subject: My last day of work',
   '',
   'Dear [manager name],',
   '',
   'I am writing to let you know that my last day of work will be [date].',
   '',
   'I am leaving the programme early and I have told CHI. I wanted to give you as much notice as I can so you can plan the schedule.',
   '',
   'Please tell me if you need anything from me before then.',
   '',
   'Thank you for the season.',
   '',
   '[Your name]',
   '[Your job title]']},
 act:{label:'File to go home early', kind:'form', url:'tally.so/r/pbLbZP'},
 w:{trigger:'Form submitted, then held. Nothing fires on submission',
  fires:'Departure date minus 1 day, two sends at once. 1. Shorten Program to the main office, carrying reason, employer, location, position, first and final day of work, whether the employer was given one week notice, and the departure city and date. 2. A reminder to the EV that they must photograph their boarding pass and send it. Both are gated on the same test: the departure has to be 16 or more days before DS End. Under 16 days neither send happens, the case stays as an internal row, and nobody is chased for proof',
  captures:'Last work day, departure date as a real date picker not free text, reason, itinerary, employer told yes or no. Email and phone are looked up from the SID rather than asked for',
  notify:'Main office only when the 16 day branch is met. Coordinator sees the row either way',
  log:'Case row, category Compliance, Early Departure. Proof of return chase scheduled for departure plus 3 and plus 7',
  status:'fix',
  note:'Highest value build on the board. Form is live at tally.so/r/pbLbZP. Programme Shortening is the largest single case type in the tracker at 21 of 213 and it costs only 23 replies, because it already moved to a form. Four things have to be right. The trigger watches the date rather than firing and forgetting, because people move flights constantly. A submission whose departure date has already passed fires immediately instead of waiting for a date in the past. 15 versus 16 days is a sharp boundary, so the departure field must be a real date picker and DS End must be correct on the roster. And the day before matters: on the day itself they are already travelling, so the boarding pass reminder has to reach them while they can still act on it. The proof itself is a second short form with one required upload field and example photos of a boarding pass stub and a luggage tag, chased at departure plus 3 and plus 7. It has to be an upload field, not an email reply, because a reply lets people send words instead of files: one sent a booking confirmation, one sent the wrong document, and one replied with the template placeholder still in the message and nothing attached. There is no tile for it, on purpose. Nobody comes looking for proof of return, it is pushed to them by the trigger. Existing bugs to clear first: the form has no email or phone field, and the proof of return address is wrong in three separate places'}},
{s:'end', q:'When do I have to leave the United States', sub:'Grace period, 30 days, last date', r:'Team', ic:'hourglass', k:'grace period 30 days leave country last date when go home stay after insurance uninsured no work travel insurance',
 you:"Your programme ends <b>{dsEndF|your DS end date}</b>. The 30-day grace period starts on your last day of work.[[ That day is <b>{lastDayWorkedF}</b>. It ends <b>{graceEnd}</b>.]] You cannot work in the grace period.",
 lead:"You cannot extend your J-1 or your DS-2019. The 30-day grace period starts on your last day of work. You may stay up to 30 days after that day. No work is allowed.",
 body:["Your last work day is the day you actually stop working, not the end date on the DS-2019 by itself. The 30-day grace period starts that day. If you finish 15 days or fewer before the DS end date, CHI may not need a SEVIS shorten. Still tell your coordinator.","Travel inside the United States during the grace period is allowed. If you leave the country, including on a cruise, the grace period ends. You cannot come back in on this visa.","CHI insurance ends on <b>{dsEndF|your DS end date}</b>, not at the end of the grace period. Consider travel insurance.","Unsure of the date you must be home for school? Message my CHI team."],
 need:["The end date on your DS-2019","Your university term start, if it matters"],
 act:{label:'Message my CHI team', kind:'chi'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Routes to the agency named from Agency Office Code. Written this way because CHI has been asked to confirm return dates it cannot know.'}},
{s:'end', q:'Can I travel before I go home', sub:'Travel at the end, grace period', r:'Answer', ic:'depart', k:'travel outside us canada mexico cruise grace period leave country re enter signature end of program trip re-entry',
 you:'Your programme ends <b>{dsEndF}</b>. The grace period is 30 days from your last day of work.[[ You may stay until <b>{graceEnd}</b>.]] Any trip outside the United States has to bring you back before <b>{dsEndF}</b>. After that date you cannot re-enter at all.',
 lead:'It depends on one thing. Are you travelling before your end date, or after it?',
 body:['BEFORE your end date, do the four steps.','One. Check your visa says Entries M. Two. Get your employer to say yes in writing. Three. Request a travel signature 2 weeks ahead. Email a clear photo of your whole DS-2019 to CHIWT@chinet.org.','Four. Your return flight must land in the United States BEFORE your end date. Not on that day. Before it. If you come back after that date, you will not be let in.','After your last day of work you are in your 30-day grace period. That is a short time you are allowed to stay. It does not start on the DS end date unless that was also your last day of work.','In your grace period you can travel inside the United States. That is fine.','But if you leave the country in your grace period, it ends the moment you go. You cannot come back. Not even the next day.','Puerto Rico is part of the United States. A trip there is not leaving. No signature needed.','A cruise that stops in another country IS leaving. Even if it starts and ends at a US port.'],
 clock:{l:'Before you book anything', t:'Request a travel signature 2 weeks ahead. Only ask for one if you will be back before your programme end date.'},
 need:['Your visa, to check the word Entries','A clear photo of your whole DS-2019','Your employer saying yes, in writing','The day you leave and the day you come back'],
 act:{label:'Send me the travel guide', kind:'template'},
 w:{trigger:'Tile opened or action tapped', fires:'Travel Outside US template', captures:'Nothing on view', notify:'Signature request goes to CHIWT, not to the coordinator', log:'Send logged against SID', status:'fix', note:'Same template as the working stage tile and the same missing name merge field. The end of programme wording has to differ, because after DS End there is no signature to give and the real answer is that leaving ends the grace period. Worth splitting the template in two, or adding one paragraph that fires only when DS End is inside 30 days.'}},
{s:'end', q:'How do I extend my insurance for my travel period', sub:'Cover after my programme ends', r:'File', ic:'shieldplus', k:'insurance extend cover grace period travel after end medical health uninsured buy extension fee envisage teladoc 50 dollars supplement',
 you:"You are covered from <b>{insStartF}</b> to <b>{dsEndF}</b>. The grace period does not extend that cover unless you buy more.",
 lead:"CHI cover ends on your programme end date. The grace period does not extend it.",
 body:["Message my CHI team before <b>{dsEndF|your end date}</b> to buy the travel-period supplement. The fee is 50 dollars. Pay by card when CHI sends the request.","After the cover stops, it usually cannot be added back.","You are also not covered outside the United States for ordinary tourist time, unless you buy separate travel insurance.","Teladoc and DialCare work in the USA only. They stop when the cover ends."],
 clock:{l:'Ask before your end date', t:'Once cover has lapsed it usually cannot be added back. Ask while your programme is still running.'},
 need:["The dates you want covered","Your flight home","Your programme end date"],
 act:{label:'Ask about extending my insurance', kind:'form'},
 w:{trigger:'DS End minus 21, and on tile open', fires:'Insurance extension options with a cost per week', captures:'Dates requested, flight home date', notify:'Coordinator', log:'Case row, category Compliance. Extension dates written to the roster', status:'build', note:'The mirror image of the early arrival gap, and neither trigger exists yet. Both are the same failure: insurance runs DS Start to DS End and nothing watches either edge. The early end cost about 1450 dollars of exposure across 14 people this season. The late end is not measured at all, because nobody asks until they are already uninsured and usually already sick.'}},
{s:'end', q:'How do I get my final paycheck', sub:'Last pay, after I stop working', r:'Answer', ic:'finalpay', k:'final paycheck last pay wages after leaving money owed direct deposit close bank account payroll last check w2 2FA check bounced check declined name wrong on check missing hours training hours last check final check after I leave employer directly',
 you:"Your programme ends <b>{dsEndF}</b>. Ask <b>{employer|your employer}</b> payroll before your last shift for the final pay date, and how the money will reach you.",
 lead:"Ask while you are still there.",
 body:["The money often comes one or two pay periods later. Ask whether the last pay can go to an ATM or stay on the card.","If the check arrives after you leave, contact your employer directly to arrange it. CHI does not receive it, mail it, or deposit it for you.","Before you leave, update your address with your employer and with your bank. CHI does not take your mail.","Do not close your U.S. bank yet. Keep it open through tax filing.","Give your employer the address that will still work for your W-2 in January.","Move two-factor login to your email before you cancel your U.S. phone number. Use only your own account.","Keep your last pay stub."],
 need:["Your last day","The pay date","The address payroll has","Your bank is still open"],
 sample:{title:'Email you can send payroll', lines:[
   'Subject: My final paycheck',
   '',
   'Dear [manager or payroll],',
   '',
   'My last day of work is [date]. Please can you tell me three things:',
   '',
   '1. What date my final pay will be issued',
   '2. Whether it will be direct deposit or a check sent in the post',
   '3. If it is sent in the post, what address you have for me',
   '',
   'I want to make sure it reaches me after I leave. Please use the same address for my W-2 in January.',
   '',
   'Thank you,',
   '[Your name]',
   '[Your job title]']},
 act:{label:'Ask my CHI team about my final pay', kind:'team'},
 w:{trigger:'DS End minus 14, together with the W-2 send', fires:'Final pay and forwarding address reminder', captures:'Forwarding address if submitted', notify:'Coordinator only if the participant reports it never arrived', log:'Send logged against SID', status:'build', note:'No template written. This and the W-2 tile ask for the same thing, a working address after departure, so they should be one send at DS End minus 14 rather than two. Chasing a final paycheck after someone has flown and closed their account is the expensive version of this conversation.'}},
{s:'end', q:'Should I close my US bank account', sub:'Closing the account, final pay, overages', r:'Answer', ic:'bankclose', k:'close bank account keep open final pay overage overages refund tax money dormant fee statement 2FA account closed bank blocked cant log in abroad wise revolut chase refused wisely sent money by mistake',
 you:"Your programme ends <b>{dsEndF}</b>. Get the final pay date from <b>{employer|your employer}</b> first.",
 lead:"Not yet. Wait until the final pay, and any refund, has arrived.",
 body:["Tax money can arrive months later. Sprintax tells you whether you get a refund or you owe.","A bank refused you? Try another major bank. Each one decides for itself.","Make sure your email works from home before you leave. Most banks send login codes there. Do not send those codes to anyone. Before you leave, update your address with your employer and with your bank. CHI does not take your mail. Keep the account open until your final pay and any tax refund arrive. Ask how to close it from abroad, and leave a small balance for fees.","Ask the bank how to close the account from abroad, and what they charge if you are not using it.","Move two-factor login to your email before you lose your U.S. phone number.","Never leave your login with a roommate. Use only your own account."],
 need:["Your final pay date","Are you claiming a tax overage?","What the bank charges"],
 act:{label:'Ask my CHI team', kind:'team'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Belongs in the same DS End minus 14 send as the final pay and W-2 reminder. All three are the same underlying problem: money that arrives after the participant has gone.'}},
{s:'end', q:'How do I claim my tax overages back', sub:'W-2, filing, and tax taken in error', r:'Answer', ic:'formpct', k:'w2 w-2 tax overage overages back claim return irs file january april deadline fica oasdi social security medicare 843 8316 nonresident nonresident alien overpaid too much tax 1040-nr sprintax turbotax march',
 you:"<b>{employer|Your employer}</b> sends your W-2 by January 31. Before you leave, update your address with your employer and with your bank. CHI does not take your mail.",
 lead:"There are two paths.",
 body:["Too much income tax comes back on Form 1040-NR. File it from home between February 1 and April 15, using Sprintax at https://www.sprintax.com . Do not use TurboTax.","Many W-2s arrive in February. Do not chase a missing one before March 1. Check that the Social Security number on it is yours. A second job that was never approved is your own W-2 problem.","{winterTaxNote|omit}","Social Security or Medicare tax taken by mistake: ask <b>{employer|your employer}</b> to refund it while you still work there. If they will not, use IRS Forms 843 and 8316. Sprintax can help later. That way is slow.","Keep your U.S. bank open.","Save your last pay stub. It is the backup if the W-2 is late. CHI will not collect a W-2 from a second job that was never approved.","On the W-4, Single and 0 exemptions is the setting that leaves a refund possible.","CHI staff are not tax advisors and cannot fill in the forms. Nobody needs your bank login."],
 clock:{l:'Before you fly home', t:'Give payroll an address that still works in January, and do not close your US bank account until everything owed to you has arrived.'},
 need:["Your W-2","A pay stub","An address that works in January","Your visa page and I-94, if you are claiming the Social Security tax"],
 act:{label:'Read this and go back', kind:'answer'},
 w:{trigger:'Tile opened, and on a send at DS End minus 14', fires:'Nothing on view', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Two questions were being answered as one and they have nothing in common. The April return returns an income tax overage. Social Security and Medicare taken in error never comes back that way, and every participant who is told to just file gets nothing and asks again a year later. The employer first line is the one that matters most, because inside the same tax year payroll can simply correct it, and after that year closes the participant is into Form 843 and a wait of most of a year. Pairs with the payroll tile on the working board, which is where this gets caught early enough to still be cheap.'}},
{s:'end', q:'Can I come back next year', sub:'Returning, next season, second time', r:'Answer', ic:'calrefresh', k:'come back next year again return second season returnee repeat apply final evaluation monthly come back again next summer position id switch store same employer 3-year three year self-placement letter of intent no self placement',
 you:"You are in <b>{country|your country}</b>, for <b>{season|this season}</b>.[[ Returnee on file: <b>{returnee}</b>.]][[ Times on the programme: <b>{timesParticipated}</b>.]] Want to work for <b>{employer|your employer}</b> again? Tell your CHI team.",
 lead:"Yes, if you are still a full-time student. CHI has a 3-year maximum.",
 body:["Message my CHI team early. Tell them you want to come back next year, including for a second season.","Stay in good standing. Finish the monthly evaluations, clear your rent, and avoid a program-review warning.","If <b>{employer|your employer}</b> may take you again, CHI confirms that with them. Do not ask the employer for your own offer. That is self-placement, and CHI will not issue a DS-2019 for it.","You can ask CHI for a different department or store. The employer decides.","Returning participants sign a letter of intent to stay the full season.","Complete the final evaluation at wt.chinet.org, even after you are home.","Monthly evaluation status: <b>{monthlyEvalStatus|omit}</b>."],
 need:["Proof you are still a student"],
 act:{label:'Tell my CHI team I want to return', kind:'form'},
 w:{trigger:'DS End minus 14, plus tile', fires:'Returnee interest confirmation', captures:'Interest, preferred employer, student status', notify:'Coordinator digest at season end', log:'Roster flag for next season recruitment', status:'build', note:'Not a failure question, an interest question. EYW participants raise it at 47 percent against a 10 percent baseline. Send it as an offer, not a correction.'}},
{s:'home', q:'Help me find housing', sub:'Where to look, what to check, before you pay', hz:1, g:'Before you fly', ic:'housekey', r:'Team', k:'find housing looking for housing need a place no housing house apartment room airbnb facebook housing j1 housing cheaper too expensive budget roommate housing far from work distance',
 you:"You are placed with <b>{employer|your employer}</b> in <b>{location|your town}</b>.[[ Housing status: <b>{housingStatus}</b>.]]",
 lead:"Choose housing you can get to work from, and send it to us before you pay anything.",
 body:["Look in your employer's WhatsApp group first.[[ The group on file is <b>{waGroupName}</b>.]] Past participants share rooms there.","Check the commute before you book. Housing more than a short bike or bus ride from <b>{employerCity|your job}</b> will cost you shifts.","Booking a short-term rental? Keep every message and payment inside the app. If the place is unusable, report it in the app the same day, with photos. Do not ask your bank to reverse the charge while the app is still reviewing it.","Once you have an address, verify it in the portal at least 4 weeks before you arrive.","Housing is one of three types. Employer-provided, CHI-assisted, or you arrange it yourself. Your job offer says which one you have.","The deposit is the landlord's money once you pay it. You get it back only if you meet every condition of the lease. CHI cannot negotiate the deposit or the room.","Do not wire a large sum before you see the place. A hostel or a short-term rental for the first week lets you view a room in person. A video tour is the backup if you must book from home.","Do not sign a lease longer than your stay. You will not get that deposit back.","Check-in hours are fixed. If you land after check-in closes, use a hotel until it opens.","You need at least 1,500 dollars for your first weeks: deposit, rent, and food before your first paycheck."],
 need:["The listing","The address","How you will get to work"],
 act:{label:'Ask CHI to check this housing', kind:'team'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'Listing and address', notify:'Coordinator', log:'Page view plus a case only if they ask', status:'build', note:'Finding housing was a missing topic. Verification stays on the verify tile.'}},
{s:'arr', q:'When do I start working', sub:'Waiting for my schedule, onboarding, E-Verify', ic:'doorin', r:'Answer', k:'when do i start start working start work no schedule not on the schedule havent called me waiting for training training date onboarding paylocity paycom workday ukg adp e-verify i-9 rejected tentative nonconfirmation mismatch documents pending first shift start day',
 you:"<b>{employer|Your employer}</b> expects you from <b>{dsStartF|your DS start date}</b>.[[ Your SEVIS status is <b>{sevisStatus}</b>.]]",
 lead:"Your start date on the DS-2019 is the first day you are allowed to work, not a promised first shift. Paperwork comes first, then training is scheduled.",
 body:["Validate your SEVIS record within 3 days of arriving. Your employer cannot finish your paperwork until you are active.","Fill in every onboarding task in the employer's app. Upload your passport, visa, DS-2019, and I-94. Do not pick a U.S. passport document type.","No Social Security number yet? Ask your employer first. You can enter 999-99-9999. Never guess a number that is not yours.","E-Verify mismatch or tentative nonconfirmation? Do the steps the employer gives you that day, then email your coordinator.","Five working days after you are active and still no schedule? Email your manager, then your coordinator."],
 need:["Your passport, visa, DS-2019, and I-94","The name of the employer's app"],
 act:{label:'I still have no schedule', kind:'chi'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Onboarding and E-Verify were missing from the menu.'}},
{s:'work', q:'Can I change my position or department', sub:'Department, store, or job title', g:'Adding or changing my job', ic:'swap', r:'Team', k:'change department change position switch to foods cashier deli produce different store location change scheduled as something else union rate pay rate',
 you:"Your offer says <b>{job|your position}</b> at <b>{employer|your employer}</b> in <b>{location|your location}</b>.",
 lead:"Your employer decides your department. CHI cannot change it, but tell us if your work is very different from your offer.",
 body:["Ask <b>{managerName|your manager}</b> first, in writing.","Pay can differ between departments.","Scheduled for a job very different from your offer? Email your coordinator before you refuse a shift."],
 need:["What you were scheduled to do","What your offer says"],
 act:{label:'Message my CHI team', kind:'chi'},
 w:{trigger:'Form submitted', fires:'Nothing automatic', captures:'What changed', notify:'Coordinator', log:'Case row only if they write in', status:'build', note:'Position and department changes were a missing topic.'}},
{s:'work', q:'My monthly evaluation', sub:'Monthly report, cancel status', g:'My hours and my pay', ic:'formsign', r:'Team', k:'monthly evaluation monthly report evaluation survey cancel status cancelled status forgot evaluation',
 lead:"Your monthly evaluation is required. Missing it can put your program in cancel status.",
 body:["It arrives by email every month. Fill it in the day you get it.","Lost your phone? Call CHI at 1-800-432-4643, ext. 0. That line is open 24/7. Never send a password or a login code.","Left a second job? Say so in your next evaluation.","Status on file: <b>{monthlyEvalStatus|omit}</b>."],
 need:["The month you missed, if you know it"],
 act:{label:'I missed my evaluation', kind:'chi'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody until they write in', log:'Page view only', status:'build', note:'No roster due date yet, so the next-steps card does not remind them automatically.'}},
{s:'life', q:'Who do I contact for help', sub:'Employer, landlord, CHI, or insurance', g:'Who to ask', ic:'askbubble', r:'Answer', k:'who to ask who to contact who do I ask CHI or employer landlord deposit schedule rent insurance img coordinator help routing',
 you:"Your coordinator is <b>{coordinator|your CHI team}</b>. Your employer is <b>{employer|your employer}</b>.[[ Your manager is <b>{managerName}</b>.]]",
 lead:"Use the right person first. That is faster than writing to everyone.",
 body:["Employer, manager, or HR: onboarding, schedule, hours, attendance, paychecks, taxes on the stub, uniform, training, job duties, and coworker problems. Social Security or Medicare on your check? Ask payroll first. If they do not fix it, Message my CHI team.","Landlord: trash, utilities, rent, deposit, keys, check-in time, broken things, house rules, and guests. CHI cannot negotiate your deposit or your room.","CHI, through Message my CHI team: SEVIS validation, second-job approval, an address, a monthly evaluation, travel outside the United States, and an employer problem that HR will not fix. That button opens an email to your coordinator.","Insurance card, a doctor, a bill, or a claim: the Envisage Student Zone, or IMG at 1-855-731-9445.","CHI cannot book or change your flight, change your schedule, your hours, your pay rate, or your room, or get your deposit back.","If you are in danger, open the unsafe tile."],
 need:[],
 act:{label:'Message my CHI team', kind:'chi'},
 w:{trigger:'Tile opened', fires:'Nothing sends', captures:'Nothing', notify:'Nobody', log:'Page view only', status:'build', note:'Who Does What, with no instruction to contact a sending partner.'}}
];


